  // Initialize UI language state
  setLanguage(currentLang);

  // Initialize Timezone Dropdown (UTC-12 to UTC+14)
  for (let tz = -12; tz <= 14; tz++) {
    const opt = document.createElement('option');
    opt.value = tz;
    opt.textContent = `UTC${tz >= 0 ? '+' : ''}${tz}:00`;
    if (tz === 8) opt.selected = true; // Default Beijing UTC+8
    timezoneSelect.appendChild(opt);
  }

  // Initialize Global City Dropdown and Cascading Birth Location Controller
  function populateLegacyCitySelect() {
    if (!citySelect) return;
    citySelect.innerHTML = '';
    GLOBAL_REGIONS.forEach(reg => {
      const group = document.createElement('optgroup');
      group.label = reg.group;
      reg.cities.forEach(c => {
        const opt = document.createElement('option');
        opt.value = JSON.stringify({ lon: c.lon, tz: c.tz });
        const lonStr = c.lon >= 0 ? `${c.lon.toFixed(2)}°E` : `${Math.abs(c.lon).toFixed(2)}°W`;
        opt.textContent = `${c.name} (${lonStr}, UTC${c.tz >= 0 ? '+' : ''}${c.tz})`;
        group.appendChild(opt);
      });
      citySelect.appendChild(group);
    });
  }

  function initBirthLocationCascader() {
    populateLegacyCitySelect();

    if (!birthCountrySelect || !birthProvinceSelect || !birthCitySelect) {
      if (citySelect) {
        citySelect.selectedIndex = 0;
        customLonInput.value = '116.40';
        timezoneSelect.value = '8';
      }
      return;
    }

    // 1. Populate Country Select
    function populateCountries(selectedCountryId) {
      birthCountrySelect.innerHTML = '';
      const isEn = (currentLang === 'en');
      GLOBAL_BIRTH_REGIONS.forEach(c => {
        const opt = document.createElement('option');
        opt.value = c.countryId;
        opt.textContent = isEn ? c.countryNameEn : c.countryNameZh;
        if (c.countryId === selectedCountryId) opt.selected = true;
        birthCountrySelect.appendChild(opt);
      });
      if (!selectedCountryId && GLOBAL_BIRTH_REGIONS.length > 0) {
        birthCountrySelect.value = 'china';
      }
    }

    // 2. Populate Province/State Select
    function populateProvinces(countryId, selectedProvId) {
      birthProvinceSelect.innerHTML = '';
      const isEn = (currentLang === 'en');
      const country = GLOBAL_BIRTH_REGIONS.find(c => c.countryId === countryId) || GLOBAL_BIRTH_REGIONS[0];
      if (!country) return;

      country.provinces.forEach(p => {
        const opt = document.createElement('option');
        opt.value = p.id;
        opt.textContent = isEn ? p.nameEn : p.nameZh;
        if (p.id === selectedProvId) opt.selected = true;
        birthProvinceSelect.appendChild(opt);
      });
      if (!selectedProvId && country.provinces.length > 0) {
        birthProvinceSelect.value = country.provinces[0].id;
      }
    }

    // 3. Populate Cities Select (Each Province/State has 3 Anchor Cities; Direct Municipalities listed directly)
    function populateCities(countryId, provId, selectedCityIdx) {
      birthCitySelect.innerHTML = '';
      const isEn = (currentLang === 'en');
      const country = GLOBAL_BIRTH_REGIONS.find(c => c.countryId === countryId) || GLOBAL_BIRTH_REGIONS[0];
      if (!country) return;
      const prov = country.provinces.find(p => p.id === provId) || country.provinces[0];
      if (!prov) return;

      prov.cities.forEach((c, idx) => {
        const opt = document.createElement('option');
        opt.value = idx;
        const lonStr = c.lon >= 0 ? `${c.lon.toFixed(2)}°E` : `${Math.abs(c.lon).toFixed(2)}°W`;
        opt.textContent = isEn ? `${c.nameEn} (${lonStr})` : `${c.nameZh} · ${lonStr}`;
        if (idx === selectedCityIdx) opt.selected = true;
        birthCitySelect.appendChild(opt);
      });
      if (selectedCityIdx === undefined && prov.cities.length > 0) {
        birthCitySelect.selectedIndex = 0;
      }
    }

    function applySelectedCity() {
      const countryId = birthCountrySelect.value;
      const provId = birthProvinceSelect.value;
      const country = GLOBAL_BIRTH_REGIONS.find(c => c.countryId === countryId);
      if (!country) return;
      const prov = country.provinces.find(p => p.id === provId);
      if (!prov) return;
      const cityIdx = parseInt(birthCitySelect.value, 10) || 0;
      const city = prov.cities[cityIdx] || prov.cities[0];
      if (!city) return;

      if (customLonInput) customLonInput.value = city.lon.toFixed(2);
      if (timezoneSelect) timezoneSelect.value = String(city.tz);

      if (citySelect) {
        citySelect.value = JSON.stringify({ lon: city.lon, tz: city.tz });
      }

      if (activeMainPage === 'landing') {
        updateLandingPreview();
      } else {
        triggerCalculate();
      }
    }

    // Event listeners for cascading changes
    birthCountrySelect.addEventListener('change', () => {
      const countryId = birthCountrySelect.value;
      populateProvinces(countryId);
      const provId = birthProvinceSelect.value;
      populateCities(countryId, provId, 0);
      applySelectedCity();
    });

    birthProvinceSelect.addEventListener('change', () => {
      const countryId = birthCountrySelect.value;
      const provId = birthProvinceSelect.value;
      populateCities(countryId, provId, 0);
      applySelectedCity();
    });

    birthCitySelect.addEventListener('change', () => {
      applySelectedCity();
    });

    // Initial setup: China -> Municipalities -> Beijing
    populateCountries('china');
    populateProvinces('china', 'municipalities');
    populateCities('china', 'municipalities', 0);

    // Initial coordinates
    if (customLonInput) customLonInput.value = '116.40';
    if (timezoneSelect) timezoneSelect.value = '8';
    if (citySelect) {
      citySelect.value = JSON.stringify({ lon: 116.4, tz: 8 });
    }

    // Bidirectional sync helper for coordinates
    window.syncBirthLocationCascader = function(targetLon, targetTz) {
      if (targetLon === undefined) return;
      const tLon = parseFloat(targetLon);
      const tTz = targetTz !== undefined ? parseInt(targetTz, 10) : 8;

      let bestMatch = null;
      let minDiff = 999999;

      GLOBAL_BIRTH_REGIONS.forEach(c => {
        c.provinces.forEach(p => {
          p.cities.forEach((city, cIdx) => {
            const diff = Math.abs(city.lon - tLon) + Math.abs(city.tz - tTz) * 5;
            if (diff < minDiff) {
              minDiff = diff;
              bestMatch = { countryId: c.countryId, provId: p.id, cityIdx: cIdx };
            }
          });
        });
      });

      if (bestMatch && minDiff < 3) {
        birthCountrySelect.value = bestMatch.countryId;
        populateProvinces(bestMatch.countryId, bestMatch.provId);
        populateCities(bestMatch.countryId, bestMatch.provId, bestMatch.cityIdx);
      }
    };

    window.refreshBirthLocationLabels = function(lang) {
      const curCountry = birthCountrySelect.value;
      const curProv = birthProvinceSelect.value;
      const curCityIdx = parseInt(birthCitySelect.value, 10) || 0;
      populateCountries(curCountry);
      populateProvinces(curCountry, curProv);
      populateCities(curCountry, curProv, curCityIdx);
    };
  }

  // Initialize Cascading Birth Location System
  initBirthLocationCascader();

  // Preserved citySelect listener
  if (citySelect) {
    citySelect.addEventListener('change', () => {
      try {
        const val = JSON.parse(citySelect.value);
        if (customLonInput) customLonInput.value = parseFloat(val.lon).toFixed(2);
        if (timezoneSelect) timezoneSelect.value = val.tz;
        if (typeof window !== 'undefined' && window.syncBirthLocationCascader) {
          window.syncBirthLocationCascader(val.lon, val.tz);
        }
        if (activeMainPage === 'landing') {
          updateLandingPreview();
        } else {
          triggerCalculate();
        }
      } catch (e) {}
    });
  }

  timezoneSelect.addEventListener('change', () => {
    if (activeMainPage === 'landing') {
      updateLandingPreview();
    } else {
      triggerCalculate();
    }
  });

  // Current Residence City Controls
  function populateCurrentCityOptions(countryKey, selectedCityId) {
    if (!currentCitySelect) return;
    currentCitySelect.innerHTML = '';
    const isEn = (currentLang === 'en');
    const db = (typeof SpatialFengShuiEngine !== 'undefined') ? SpatialFengShuiEngine.GEO_CITIES_DATABASE : null;
    const countryData = (db && db[countryKey]) ? db[countryKey] : (db ? db.China : null);
    if (!countryData) return;

    Object.keys(countryData.regions).forEach(regKey => {
      const reg = countryData.regions[regKey];
      const optgroup = document.createElement('optgroup');
      optgroup.label = isEn ? `${reg.directionEn} (${reg.elementHeavenlyEn})` : `${reg.directionZh} (${reg.elementHeavenlyZh})`;
      reg.cities.forEach(c => {
        const opt = document.createElement('option');
        opt.value = c.id;
        const cDir = isEn ? (c.directionEn || reg.directionEn) : (c.directionZh || reg.directionZh);
        const cElem = isEn ? (c.elementEn || reg.elementEn) : (c.elementHeavenlyZh || reg.elementHeavenlyZh);
        opt.textContent = isEn ? `${c.nameEn} · ${cDir} (${cElem})` : `${c.nameZh} · ${cElem}`;
        if (c.id === selectedCityId) {
          opt.selected = true;
        }
        optgroup.appendChild(opt);
      });
      currentCitySelect.appendChild(optgroup);
    });

    const customOpt = document.createElement('option');
    customOpt.value = 'custom';
    customOpt.textContent = isEn ? 'Other / Custom City...' : '其他 / 自定义城市...';
    if (selectedCityId === 'custom') customOpt.selected = true;
    currentCitySelect.appendChild(customOpt);

    currentCitySelect.value = selectedCityId;

    if (currentCustomCityInput) {
      if (currentCitySelect.value === 'custom') {
        currentCustomCityInput.classList.remove('hidden');
      } else {
        currentCustomCityInput.classList.add('hidden');
      }
    }
  }

  if (currentCountrySelect) {
    currentCountrySelect.value = currentResidenceCountry;
    currentCountrySelect.addEventListener('change', () => {
      currentResidenceCountry = currentCountrySelect.value;
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('current_residence_country', currentResidenceCountry);
      }
      const db = (typeof SpatialFengShuiEngine !== 'undefined') ? SpatialFengShuiEngine.GEO_CITIES_DATABASE : null;
      const countryData = db ? db[currentResidenceCountry] : null;
      const firstReg = countryData ? Object.values(countryData.regions)[0] : null;
      currentResidenceCity = (firstReg && firstReg.cities[0]) ? firstReg.cities[0].id : 'custom';
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('current_residence_city', currentResidenceCity);
      }
      populateCurrentCityOptions(currentResidenceCountry, currentResidenceCity);
      if (currentBaziResult && typeof renderSpatialFengShui === 'function') {
        renderSpatialFengShui(currentBaziResult, currentLuckResult);
      }
    });
  }

  if (currentCitySelect) {
    currentCitySelect.addEventListener('change', () => {
      currentResidenceCity = currentCitySelect.value;
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('current_residence_city', currentResidenceCity);
      }
      if (currentCustomCityInput) {
        if (currentCitySelect.value === 'custom') {
          currentCustomCityInput.classList.remove('hidden');
          if (typeof currentCustomCityInput.focus === 'function') {
            currentCustomCityInput.focus();
          }
        } else {
          currentCustomCityInput.classList.add('hidden');
        }
      }
      if (currentBaziResult && typeof renderSpatialFengShui === 'function') {
        renderSpatialFengShui(currentBaziResult, currentLuckResult);
      }
    });
  }

  if (currentCustomCityInput) {
    currentCustomCityInput.value = currentResidenceCustomName;
    currentCustomCityInput.addEventListener('input', () => {
      currentResidenceCustomName = currentCustomCityInput.value.trim();
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('current_residence_custom', currentResidenceCustomName);
      }
      if (currentBaziResult && typeof renderSpatialFengShui === 'function') {
        renderSpatialFengShui(currentBaziResult, currentLuckResult);
      }
    });
  }

  // Initialize City Dropdown Options
  populateCurrentCityOptions(currentResidenceCountry, currentResidenceCity);

  customLonInput.addEventListener('input', () => {
    if (activeMainPage === 'landing') {
      updateLandingPreview();
    } else {
      debouncedCalculate(60);
    }
  });

  // Theme Toggle & Persistence
  try {
    const savedTheme = (typeof localStorage !== 'undefined') ? localStorage.getItem('bazi_theme') : null;
    if (savedTheme === 'light') {
      if (document.documentElement && typeof document.documentElement.setAttribute === 'function') {
        document.documentElement.setAttribute('data-theme', 'light');
      }
      if (document.documentElement && document.documentElement.classList && typeof document.documentElement.classList.add === 'function') {
        document.documentElement.classList.add('light');
      }
      if (document.body && document.body.classList && typeof document.body.classList.add === 'function') {
        document.body.classList.add('light-theme');
      }
      if (themeToggle) {
        themeToggle.textContent = '☀️ 浅昼';
      }
    }
  } catch (e) {}

  if (themeToggle) {
    themeToggle.addEventListener('click', () => {
      const currentTheme = (document.documentElement && typeof document.documentElement.getAttribute === 'function') ? (document.documentElement.getAttribute('data-theme') || 'dark') : 'dark';
      const newTheme = currentTheme === 'dark' ? 'light' : 'dark';
      if (document.documentElement && typeof document.documentElement.setAttribute === 'function') {
        document.documentElement.setAttribute('data-theme', newTheme);
      }
      if (newTheme === 'light') {
        if (document.documentElement && document.documentElement.classList && typeof document.documentElement.classList.add === 'function') {
          document.documentElement.classList.add('light');
        }
        if (document.body && document.body.classList && typeof document.body.classList.add === 'function') {
          document.body.classList.add('light-theme');
        }
      } else {
        if (document.documentElement && document.documentElement.classList && typeof document.documentElement.classList.remove === 'function') {
          document.documentElement.classList.remove('light');
        }
        if (document.body && document.body.classList && typeof document.body.classList.remove === 'function') {
          document.body.classList.remove('light-theme');
        }
      }
      try {
        if (typeof localStorage !== 'undefined') {
          localStorage.setItem('bazi_theme', newTheme);
        }
      } catch (e) {}
      themeToggle.textContent = newTheme === 'dark' ? '🌙 暗夜' : '☀️ 浅昼';
      if (currentBaziResult) {
        ElementChart.renderRadar('elementRadarCanvas', currentBaziResult.elements.percentages);
        if (typeof renderPhasePortrait === 'function') {
          renderPhasePortrait(currentBaziResult, currentLuckResult);
        }
      }
      if (typeof currentLuckResult !== 'undefined' && currentLuckResult && currentLuckResult.timeline && typeof drawChronoTimelineChart === 'function') {
        drawChronoTimelineChart(currentLuckResult.timeline, typeof activeChronoAge !== 'undefined' ? activeChronoAge : 1);
      }
      if (typeof drawDualSynastryTimelineChart === 'function' && typeof synastryTimelineA !== 'undefined' && synastryTimelineA.length > 0) {
        drawDualSynastryTimelineChart(currentLang === 'en');
      }
      if (typeof drawCurrentDualPhaseManifold === 'function' && cachedSynastryPhaseDerived && document.getElementById('synastryPhaseCanvas')) {
        drawCurrentDualPhaseManifold(currentLang === 'en');
      }
      if (typeof window !== 'undefined' && window.__lastSimulationResult && window.__lastSimulationResult.bifurcationDynamics && typeof PhasePortraitEngine !== 'undefined' && typeof PhasePortraitEngine.renderDualTrackBifurcation === 'function') {
        PhasePortraitEngine.renderDualTrackBifurcation('simBifurcationCanvas', window.__lastSimulationResult.bifurcationDynamics, newTheme === 'dark', currentLang);
      }
    });
  }

  // Set Default Time to Current Local Time
  function setCurrentTime() {
    const now = new Date();
    const y = now.getFullYear();
    const m = String(now.getMonth() + 1).padStart(2, '0');
    const d = String(now.getDate()).padStart(2, '0');
    if (birthDatePicker) birthDatePicker.value = `${y}-${m}-${d}`;

    const h = String(now.getHours()).padStart(2, '0');
    const min = String(now.getMinutes()).padStart(2, '0');
    if (birthTimePicker) birthTimePicker.value = `${h}:${min}`;
  }
  setCurrentTime();

  // Reset Natal Inputs & Recalculate with Actual Real-World Time
  function resetToActualCurrentTime() {
    setCurrentTime();
    if (genderSelect) genderSelect.value = '乾造';
    if (useSolarTimeCheck) useSolarTimeCheck.checked = false;
    if (portalPresetsContainer) {
      const presetBtns = portalPresetsContainer.querySelectorAll('.archetype-preset-card');
      presetBtns.forEach(b => {
        if (b.getAttribute('data-preset') === 'now') b.classList.add('active');
        else b.classList.remove('active');
      });
    }
    triggerCalculate();
    updateLandingPreview();
    if (activeMainPage === 'dashboard') {
      updateDashboardSummaryBar();
    }
  }

  nowBtn.addEventListener('click', resetToActualCurrentTime);

  const btnResetToActualTime = document.getElementById('btnResetToActualTime');
  if (btnResetToActualTime) {
    btnResetToActualTime.addEventListener('click', resetToActualCurrentTime);
  }

  const btnResetToActualTimeTop = document.getElementById('btnResetToActualTimeTop');
  if (btnResetToActualTimeTop) {
    btnResetToActualTimeTop.addEventListener('click', resetToActualCurrentTime);
  }

  // Element Color Class Helper
  function getElementClass(element) {
    switch (element) {
      case '木': return 'el-wood';
      case '火': return 'el-fire';
      case '土': return 'el-earth';
      case '金': return 'el-metal';
      case '水': return 'el-water';
      default: return '';
    }
  }

  function getElementBgClass(element) {
    switch (element) {
      case '木': return 'bg-el-wood';
      case '火': return 'bg-el-fire';
      case '土': return 'bg-el-earth';
      case '金': return 'bg-el-metal';
      case '水': return 'bg-el-water';
      default: return '';
    }
  }

