  function getStemElement(stem) {
    const map = { '甲':'木','乙':'木','丙':'火','丁':'火','戊':'土','己':'土','庚':'金','辛':'金','壬':'水','癸':'水' };
    return map[stem] || '木';
  }

  function getBranchElement(branch) {
    const map = { '子':'水','丑':'土','寅':'木','卯':'木','辰':'土','巳':'火','午':'火','未':'土','申':'金','酉':'金','戌':'土','亥':'水' };
    return map[branch] || '木';
  }

  function getStemShortEn(stem) {
    if (typeof I18N !== 'undefined' && I18N.STEMS && I18N.STEMS[stem]) {
      return I18N.STEMS[stem].pinyin;
    }
    const map = { '甲':'Jia','乙':'Yi','丙':'Bing','丁':'Ding','戊':'Wu','己':'Ji','庚':'Geng','辛':'Xin','壬':'Ren','癸':'Gui' };
    return map[stem] || stem;
  }

  function getBranchShortEn(branch) {
    if (typeof I18N !== 'undefined' && I18N.BRANCHES && I18N.BRANCHES[branch]) {
      return I18N.BRANCHES[branch].pinyin || I18N.BRANCHES[branch].en.split(' ')[0];
    }
    const map = { '子':'Zi','丑':'Chou','寅':'Yin','卯':'Mao','辰':'Chen','巳':'Si','午':'Wu','未':'Wei','申':'Shen','酉':'You','戌':'Xu','亥':'Hai' };
    return map[branch] || branch;
  }

  // Real-Time Solar Correction Detail Display (100% Bilingual & Reactive)
  function updateSolarDetailDisplay(res) {
    const detailEl = document.getElementById('solarCalcDetail');
    if (!detailEl) return;
    const isEn = (currentLang === 'en');
    const useTrueSolarTime = useSolarTimeCheck ? useSolarTimeCheck.checked : false;
    const timezone = (timezoneSelect && parseFloat(timezoneSelect.value) !== undefined) ? parseFloat(timezoneSelect.value) : 8.0;
    const tzSign = timezone >= 0 ? '+' : '';

    if (!useTrueSolarTime) {
      const dateStr = birthDatePicker ? birthDatePicker.value : '';
      const timeStr = birthTimePicker ? birthTimePicker.value : '';
      detailEl.innerHTML = isEn
        ? `<span class="text-gray-300"><b>Standard Clock Time:</b> ${dateStr} ${timeStr} (UTC${tzSign}${timezone}:00) · True Solar Time correction disabled.</span>`
        : `<span class="text-gray-300"><b>当地标准钟表时间：</b>${dateStr} ${timeStr}（时区 UTC${tzSign}${timezone}:00）· 当前未启用真太阳时校正。</span>`;
      return;
    }

    if (!res || !res.input) return;

    const longitude = customLonInput ? (parseFloat(customLonInput.value) || 116.4) : 116.4;
    const stdMeridian = (timezone * 15.0).toFixed(1);
    const lonDiff = (res.input.lonOffsetMinutes !== undefined) ? res.input.lonOffsetMinutes.toFixed(1) : '0.0';
    const lonSign = (res.input.lonOffsetMinutes >= 0) ? '+' : '';
    const eotVal = (res.input.eot !== undefined) ? res.input.eot.toFixed(1) : '0.0';
    const eotSign = (res.input.eot >= 0) ? '+' : '';
    const totVal = (res.input.totalSolarOffset !== undefined) ? res.input.totalSolarOffset.toFixed(1) : '0.0';
    const totSign = (res.input.totalSolarOffset >= 0) ? '+' : '';

    const adjH = String(res.input.adjustedHour !== undefined ? res.input.adjustedHour : 0).padStart(2, '0');
    const adjM = String(res.input.adjustedMinute !== undefined ? res.input.adjustedMinute : 0).padStart(2, '0');
    const lonDisplay = longitude >= 0 ? `${longitude}°E` : `${Math.abs(longitude)}°W`;

    if (isEn) {
      detailEl.innerHTML = `
        <span><b>Timezone:</b> UTC${tzSign}${timezone}:00 (${stdMeridian}°)</span>
        <span><b>Longitude:</b> ${lonDisplay}</span>
        <span><b>Lon Offset:</b> ${lonSign}${lonDiff}m</span>
        <span><b>EoT:</b> ${eotSign}${eotVal}m</span>
        <span class="text-amber-300 font-bold"><b>Total Offset:</b> ${totSign}${totVal}m ➔ <b>True Solar Time:</b> ${res.input.adjustedYear}-${String(res.input.adjustedMonth).padStart(2,'0')}-${String(res.input.adjustedDay).padStart(2,'0')} ${adjH}:${adjM}</span>
      `;
    } else {
      detailEl.innerHTML = `
        <span><b>标准时区:</b> UTC${tzSign}${timezone}:00 (${stdMeridian}°)</span>
        <span><b>出生经度:</b> ${lonDisplay}</span>
        <span><b>经度偏离:</b> ${lonSign}${lonDiff}分</span>
        <span><b>均时差:</b> ${eotSign}${eotVal}分</span>
        <span class="text-amber-300 font-bold"><b>总校正:</b> ${totSign}${totVal}分 ➔ <b>真太阳时:</b> ${res.input.adjustedYear}-${String(res.input.adjustedMonth).padStart(2,'0')}-${String(res.input.adjustedDay).padStart(2,'0')} ${adjH}:${adjM}</span>
      `;
    }
  }

  // ==========================================================================
  // Two-Stage Page Navigation (Page 1: Landing Portal / Page 2: Dashboard)
  // ==========================================================================
  function switchToDashboardView(targetView = 'view-master-profile') {
    activeMainPage = 'dashboard';
    if (landingPortalView) {
      landingPortalView.classList.add('hidden');
    }
    if (dashboardView) {
      dashboardView.classList.remove('hidden');
    }
    if (btnPortalTopNav) {
      btnPortalTopNav.classList.remove('hidden');
    }
    if (btnExportDossier) {
      btnExportDossier.classList.remove('hidden');
    }
    if (btnQuickExportSinglePdf) {
      btnQuickExportSinglePdf.classList.remove('hidden');
    }
    if (btnOpenSocialCard) {
      btnOpenSocialCard.classList.remove('hidden');
    }
    if (btnOpenSimulatorPage) {
      btnOpenSimulatorPage.classList.remove('hidden');
    }
    if (advisorFloatingToolbar) {
      advisorFloatingToolbar.classList.remove('hidden');
    }
    if (btnOpenAdvisorFloating) {
      btnOpenAdvisorFloating.classList.remove('hidden');
    }
    if (btnOpenLedgerFloating) {
      btnOpenLedgerFloating.classList.remove('hidden');
    }
    updateDashboardSummaryBar();
    const finalTarget = targetView || 'view-master-profile';
    if (typeof switchPrimaryView === 'function') {
      switchPrimaryView(finalTarget);
    }
    if (currentBaziResult && typeof ElementChart !== 'undefined') {
      ElementChart.renderRadar('elementRadarCanvas', currentBaziResult.elements.percentages);
    }
    if (typeof window !== 'undefined' && typeof window.scrollTo === 'function') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  function switchToLandingView() {
    activeMainPage = 'landing';
    if (dashboardView) {
      dashboardView.classList.add('hidden');
    }
    if (landingPortalView) {
      landingPortalView.classList.remove('hidden');
    }
    if (btnPortalTopNav) {
      btnPortalTopNav.classList.add('hidden');
    }
    if (btnExportDossier) {
      btnExportDossier.classList.add('hidden');
    }
    if (btnQuickExportSinglePdf) {
      btnQuickExportSinglePdf.classList.add('hidden');
    }
    if (btnOpenSocialCard) {
      btnOpenSocialCard.classList.add('hidden');
    }
    if (btnOpenSimulatorPage) {
      btnOpenSimulatorPage.classList.add('hidden');
    }
    if (advisorFloatingToolbar) {
      advisorFloatingToolbar.classList.add('hidden');
    }
    if (btnOpenAdvisorFloating) {
      btnOpenAdvisorFloating.classList.add('hidden');
    }
    if (btnOpenLedgerFloating) {
      btnOpenLedgerFloating.classList.add('hidden');
    }
    updateLandingPreview();
    if (typeof window !== 'undefined' && typeof window.scrollTo === 'function') {
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  if (typeof window !== 'undefined') {
    window.switchToLandingView = switchToLandingView;
    window.switchToDashboardView = switchToDashboardView;
  }
  if (typeof globalThis !== 'undefined') {
    globalThis.switchToLandingView = switchToLandingView;
    globalThis.switchToDashboardView = switchToDashboardView;
  }

  // Live Natal Preview on Landing Page
  function updateLandingPreview() {
    if (!landingQuickPreviewBox) return;
    try {
      const dateVal = birthDatePicker ? birthDatePicker.value : '';
      const timeVal = birthTimePicker ? birthTimePicker.value : '';
      if (!dateVal || !timeVal) return;

      const [year, month, day] = dateVal.split('-').map(Number);
      const [hour, minute] = timeVal.split(':').map(Number);
      const gender = genderSelect ? genderSelect.value : '乾造';
      const useTrueSolarTime = useSolarTimeCheck ? useSolarTimeCheck.checked : false;
      const isLateRatNextDay = lateRatCheck ? lateRatCheck.checked : false;
      const longitude = customLonInput ? (parseFloat(customLonInput.value) || 116.4) : 116.4;
      const timezone = (timezoneSelect && parseFloat(timezoneSelect.value) !== undefined) ? parseFloat(timezoneSelect.value) : 8.0;

      if (typeof BaZiEngine === 'undefined' || typeof BaZiEngine.calculate !== 'function') return;

      const res = BaZiEngine.calculate({
        year, month, day, hour, minute, gender,
        useTrueSolarTime, isLateRatNextDay, longitude, timezone
      });

      if (!res || !res.pillars || !res.pillars.year) return;

      // Update Real-Time Solar Display synchronously
      updateSolarDetailDisplay(res);

      // Update Visual Alchemy Elemental Harmony in real-time on the landing page
      if (typeof VisualAlchemy !== 'undefined' && res.dayMasterElement) {
        VisualAlchemy.setActiveElement(res.dayMasterElement);
      }

      // Update landing preview status badge
      if (landingPreviewStatusBadge && typeof I18N !== 'undefined') {
        landingPreviewStatusBadge.textContent = I18N.t('portal_preview_ready', currentLang);
      }

      const isEn = (currentLang === 'en');
      const pillars = [
        { labelZh: '年柱', labelEn: 'Year', p: res.pillars.year },
        { labelZh: '月柱', labelEn: 'Month', p: res.pillars.month },
        { labelZh: '日柱 (元神)', labelEn: 'Day (Self)', p: res.pillars.day, isDay: true },
        { labelZh: '时柱', labelEn: 'Hour', p: res.pillars.hour }
      ];

      const htmlPillars = pillars.map(item => {
        const p = item.p;
        if (!p) return '';
        const stemEl = getStemElement(p.stem);
        const branchEl = getBranchElement(p.branch);
        const stemClass = getElementClass(stemEl);
        const branchClass = getElementClass(branchEl);
        const stemName = isEn ? getStemShortEn(p.stem) : p.stem;
        const branchName = isEn ? getBranchShortEn(p.branch) : p.branch;
        const pNaYin = p.naYin || p.nayin || '';
        const nayin = isEn ? (typeof I18N !== 'undefined' ? I18N.getNaYin(pNaYin, 'en') : pNaYin) : pNaYin;

        const isYear = (item.labelZh === '年柱');
        const zodiacSuffix = (isYear && typeof I18N !== 'undefined') ? ` · ${I18N.getZodiac(p.branch, currentLang)}` : '';

        return `
          <div class="mini-pillar-card ${item.isDay ? 'border-amber-500/60 bg-amber-950/30 ring-1 ring-amber-500/30' : ''}">
            <div class="text-[10px] text-gray-400 font-medium pb-1">${isEn ? item.labelEn : item.labelZh}${zodiacSuffix}</div>
            <div class="text-base sm:text-lg font-bold font-serif-sc py-0.5 flex justify-center items-center gap-1">
              <span class="${stemClass}">${stemName}</span>
              <span class="${branchClass}">${branchName}</span>
            </div>
            <div class="text-[10px] text-gray-400 font-mono scale-90 truncate" title="${nayin}">${nayin}</div>
          </div>
        `;
      }).join('');

      landingQuickPreviewBox.innerHTML = htmlPillars;

      if (landingPreviewMeta && res.pillars.day) {
        const dmStem = res.pillars.day.stem;
        const dmEl = getStemElement(dmStem);
        const dmElName = isEn ? (typeof I18N !== 'undefined' ? I18N.getElement(dmEl, 'en') : dmEl) : dmEl;
        const dmEn = getStemShortEn(dmStem);
        const offsetMin = res.input && res.input.totalSolarOffset ? res.input.totalSolarOffset.toFixed(1) : '0.0';
        const offsetSign = (res.input && res.input.totalSolarOffset >= 0) ? '+' : '';

        const metaTextZh = `
          <div class="flex flex-wrap items-center justify-between gap-2">
            <div>
              <span class="text-amber-400 font-bold font-serif-sc">本命元神：${dmStem} (${dmEl})</span>
              <span class="text-gray-400 ml-2">【${res.gender}】</span>
            </div>
            <div class="text-[10px] text-gray-400">
              <span>${useTrueSolarTime ? `真太阳时偏差: <b class="text-amber-300 font-mono">${offsetSign}${offsetMin}分</b>` : '采用钟表当地时'}</span>
            </div>
          </div>
        `;

        const metaTextEn = `
          <div class="flex flex-wrap items-center justify-between gap-2">
            <div>
              <span class="text-amber-400 font-bold font-serif-sc">Day Master: ${dmEn} (${dmElName})</span>
              <span class="text-gray-400 ml-2">[${res.gender === '乾造' ? 'Qian (Male)' : 'Kun (Female)'}]</span>
            </div>
            <div class="text-[10px] text-gray-400">
              <span>${useTrueSolarTime ? `Solar Offset: <b class="text-amber-300 font-mono">${offsetSign}${offsetMin}m</b>` : 'Local Standard Time'}</span>
            </div>
          </div>
        `;

        landingPreviewMeta.innerHTML = isEn ? metaTextEn : metaTextZh;
      }
    } catch (e) {
      // ignore
    }
  }

  // Dashboard Top Summary Bar
  function updateDashboardSummaryBar() {
    if (!dashboardSummaryBadges || !currentBaziResult || !currentBaziResult.pillars || !currentBaziResult.pillars.day) return;
    const res = currentBaziResult;
    const isEn = (currentLang === 'en');

    const genderBadge = res.gender === '乾造'
      ? `<span class="px-2 py-0.5 rounded-md bg-blue-950/80 text-blue-300 border border-blue-800/40 font-bold">${isEn ? 'Qian (Male)' : '乾造 (男命)'}</span>`
      : `<span class="px-2 py-0.5 rounded-md bg-rose-950/80 text-rose-300 border border-rose-800/40 font-bold">${isEn ? 'Kun (Female)' : '坤造 (女命)'}</span>`;

    const dateStr = `${res.input.year}-${String(res.input.month).padStart(2, '0')}-${String(res.input.day).padStart(2, '0')} ${String(res.input.hour).padStart(2, '0')}:${String(res.input.minute).padStart(2, '0')}`;
    const solarStr = res.input.useTrueSolarTime
      ? `<span class="text-amber-300/90 font-mono text-[11px]">${isEn ? 'Solar: ' : '太阳时: '}${String(res.input.adjustedHour).padStart(2, '0')}:${String(res.input.adjustedMinute).padStart(2, '0')}</span>`
      : '';

    const formatPillar = (lblZh, lblEn, p) => {
      if (!p) return '';
      const stemEl = getStemElement(p.stem);
      const branchEl = getBranchElement(p.branch);
      const sCls = getElementClass(stemEl);
      const bCls = getElementClass(branchEl);
      const sName = isEn ? getStemShortEn(p.stem) : p.stem;
      const bName = isEn ? getBranchShortEn(p.branch) : p.branch;
      const sep = isEn ? '<span class="text-gray-500 font-normal">-</span>' : '';
      return `<span class="px-2 py-0.5 rounded bg-black/40 border border-gray-700 font-serif-sc font-bold"><span class="text-gray-400 text-[10px] mr-1">${isEn ? lblEn : lblZh}:</span><span class="${sCls}">${sName}</span>${sep}<span class="${bCls}">${bName}</span></span>`;
    };

    const yStr = formatPillar('年', 'Y', res.pillars.year);
    const mStr = formatPillar('月', 'M', res.pillars.month);
    const dStr = formatPillar('日', 'D', res.pillars.day);
    const hStr = formatPillar('时', 'H', res.pillars.hour);

    const dmStem = res.pillars.day.stem;
    const dmEl = getStemElement(dmStem);
    const dmElName = isEn ? (typeof I18N !== 'undefined' ? I18N.getElement(dmEl, 'en') : dmEl) : dmEl;
    const dmName = isEn ? getStemShortEn(dmStem) : dmStem;
    const dmBadge = `<span class="px-2 py-0.5 rounded bg-amber-500/10 text-amber-300 border border-amber-500/30 font-bold">${isEn ? 'Day Master: ' : '元神: '}${dmName} (${dmElName})</span>`;

    const yBranch = res.pillars.year ? res.pillars.year.branch : '';
    const zodiacAnimal = yBranch && typeof I18N !== 'undefined' ? I18N.getZodiac(yBranch, currentLang) : '';
    const zodiacBadge = zodiacAnimal ? `<span class="px-2 py-0.5 rounded bg-purple-500/10 text-purple-300 border border-purple-500/30 font-bold">${isEn ? `Zodiac: ${zodiacAnimal}` : `生肖: 属${zodiacAnimal}`}</span>` : '';

    dashboardSummaryBadges.innerHTML = `
      ${genderBadge}
      <span class="text-gray-300 font-mono text-[11px]">${dateStr}</span>
      ${solarStr ? `<span class="text-gray-500">·</span>${solarStr}` : ''}
      <span class="hidden sm:inline text-gray-500">|</span>
      <div class="flex items-center gap-1.5 flex-wrap">
        ${yStr}
        ${mStr}
        ${dStr}
        ${hStr}
      </div>
      <span class="hidden md:inline text-gray-500">|</span>
      ${dmBadge}
      ${zodiacBadge}
    `;
  }

  // Presets Controller
  function initPortalPresets() {
    if (!portalPresetsContainer) return;
    const presetBtns = portalPresetsContainer.querySelectorAll('.archetype-preset-card');
    presetBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        presetBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        const presetKey = btn.getAttribute('data-preset');
        if (presetKey === 'now') {
          resetToActualCurrentTime();
          return;
        } else if (ARCHETYPE_PRESETS[presetKey]) {
          const cfg = ARCHETYPE_PRESETS[presetKey];
          if (birthDatePicker) birthDatePicker.value = cfg.date;
          if (birthTimePicker) birthTimePicker.value = cfg.time;
          if (genderSelect) genderSelect.value = cfg.gender;
          if (customLonInput) customLonInput.value = cfg.lon.toFixed(2);
          if (timezoneSelect) timezoneSelect.value = String(cfg.tz);
          if (typeof window !== 'undefined' && window.syncBirthLocationCascader) {
            window.syncBirthLocationCascader(cfg.lon, cfg.tz);
          }
          triggerCalculate();
        }
        updateLandingPreview();
      });
    });
  }

  // Features Showcase Click on Landing Page
  function initPortalFeaturesShowcase() {
    if (!portalFeaturesGrid) return;
    portalFeaturesGrid.querySelectorAll('[data-jump-view]').forEach(card => {
      card.addEventListener('click', () => {
        const targetView = card.getAttribute('data-jump-view');
        const mode = (targetView === 'view-synastry') ? 'synastry' : (targetView === 'view-luck') ? 'chrono' : 'natal';
        triggerCalculate();
        showDynamicCalculationProgress(mode, () => {
          switchToDashboardView(targetView);
        });
      });
    });
  }

  // Advanced Solar Time Options Toggle
  function initAdvSolarToggle() {
    if (!btnToggleAdvSolar || !advSolarTimeContainer) return;
    btnToggleAdvSolar.addEventListener('click', () => {
      const isHidden = advSolarTimeContainer.classList.contains('hidden');
      if (isHidden) {
        advSolarTimeContainer.classList.remove('hidden');
        btnToggleAdvSolar.setAttribute('data-i18n', 'portal_adv_toggle_hide');
        btnToggleAdvSolar.textContent = (typeof I18N !== 'undefined') ? I18N.t('portal_adv_toggle_hide', currentLang) : (currentLang === 'en' ? '⚙️ Hide Solar Options' : '⚙️ 收起天文高级选项');
      } else {
        advSolarTimeContainer.classList.add('hidden');
        btnToggleAdvSolar.setAttribute('data-i18n', 'portal_adv_toggle_show');
        btnToggleAdvSolar.textContent = (typeof I18N !== 'undefined') ? I18N.t('portal_adv_toggle_show', currentLang) : (currentLang === 'en' ? '⚙️ Show Solar Options' : '⚙️ 展开天文高级选项');
      }
    });
  }

  // Debounce helper for high-frequency input changes
  let calcDebounceTimer = null;
  function debouncedCalculate(delay = 60) {
    if (calcDebounceTimer) clearTimeout(calcDebounceTimer);
    calcDebounceTimer = setTimeout(() => {
      triggerCalculate();
    }, delay);
  }

  // Core Calculation & UI Render (Ultra-fast synchronous execution)
  function triggerCalculate() {
    const tStart = (typeof performance !== 'undefined') ? performance.now() : Date.now();
    try {
      const dateVal = birthDatePicker.value;
      const timeVal = birthTimePicker.value;
      if (!dateVal || !timeVal) return;

      const [year, month, day] = dateVal.split('-').map(Number);
      const [hour, minute] = timeVal.split(':').map(Number);
      const gender = genderSelect.value;
      const useTrueSolarTime = useSolarTimeCheck.checked;
      const isLateRatNextDay = lateRatCheck.checked;
      const longitude = parseFloat(customLonInput.value) || 116.4;
      const timezone = parseFloat(timezoneSelect.value) !== undefined ? parseFloat(timezoneSelect.value) : 8.0;

      const result = BaZiEngine.calculate({
        year, month, day, hour, minute, gender,
        useTrueSolarTime, isLateRatNextDay, longitude, timezone
      });

      // Update Real-Time Solar Correction Detail Display (100% Bilingual & Reactive)
      updateSolarDetailDisplay(result);

      currentBaziResult = result;
      if (typeof window !== 'undefined') {
        window.currentBaziResult = currentBaziResult;
      }
      cachedIChingCycleData = null;
      window._lastRenderedHexRes = null;
      const ichingContainerEl = document.getElementById('ichingCycleContainer');
      if (ichingContainerEl) {
        if (typeof ichingContainerEl.removeAttribute === 'function') {
          ichingContainerEl.removeAttribute('data-active-tab');
          ichingContainerEl.removeAttribute('data-chart-key');
        } else {
          ichingContainerEl['data-active-tab'] = null;
          ichingContainerEl['data-chart-key'] = null;
        }
      }

      if (typeof localStorage !== 'undefined') {
        localStorage.setItem('lastBaziParams', JSON.stringify({
          year, month, day, hour, minute, gender,
          useTrueSolarTime, isLateRatNextDay, longitude, timezone,
          country: currentResidenceCountry,
          city: currentResidenceCity,
          customCity: currentResidenceCustomName
        }));
      }

      // Initialize default Luck & Decade state before rendering views
      if (typeof LuckEngine !== 'undefined') {
        const currentCalYear = new Date().getFullYear();
        selectedAnnualYear = currentCalYear;
        const userBYear = (result.input && result.input.year) || result.birthYear || result.year || currentCalYear;
        const realCurrentAge = Math.max(1, Math.min(100, currentCalYear - userBYear + 1));
        const curChronItem = (result._timelineCache && result._timelineCache.length > 0)
          ? result._timelineCache.find(d => d.year === currentCalYear)
          : null;
        activeChronoAge = curChronItem ? curChronItem.age : Math.max(1, Math.min(100, currentCalYear - userBYear + 1));
        if (!fourPillarsActiveAge || fourPillarsActiveAge < 1 || fourPillarsActiveAge > 100) {
          fourPillarsActiveAge = realCurrentAge;
        }

        currentLuckResult = LuckEngine.calculateLuck(result, selectedAnnualYear, selectedMonthBranch, selectedDailyDate);
        if (typeof window !== 'undefined') {
          window.currentLuckResult = currentLuckResult;
        }
        if (currentLuckResult && currentLuckResult.decades && currentLuckResult.decades.length > 0) {
          const matchedDecadeIdx = currentLuckResult.decades.findIndex(d => 
            selectedAnnualYear >= d.yearStart && selectedAnnualYear <= d.yearEnd
          );
          if (matchedDecadeIdx >= 0) {
            selectedDecadeIdx = matchedDecadeIdx;
          } else if (selectedDecadeIdx >= currentLuckResult.decades.length) {
            selectedDecadeIdx = 0;
          }
        }
      }

      renderChart(result);
      renderPortrait(result);
      renderLiterature(result);
      renderLuckCycles(result);
      renderZiping100Score(result);
      renderSpatialFengShui(result, currentLuckResult);
      renderFourPillarsHexagrams(result);
      if (typeof renderMasterProfile === 'function') {
        renderMasterProfile(result);
      }
      if (typeof renderCareerWealth === 'function') {
        renderCareerWealth(result, currentLuckResult);
      }
      if (typeof renderHistoricalFiguresView === 'function') {
        renderHistoricalFiguresView(result, currentLuckResult);
      }
      if (typeof renderPhasePortrait === 'function') {
        renderPhasePortrait(result, currentLuckResult);
      }
      if (typeof renderTianjiCalendarFeed === 'function') {
        renderTianjiCalendarFeed(result, currentLuckResult);
      }
      if (typeof renderPoliticalGameMatrix === 'function') {
        renderPoliticalGameMatrix(result, currentLuckResult);
      }
      if (typeof renderGeomagneticCalibrator === 'function') {
        renderGeomagneticCalibrator(result);
      }
      updateDashboardSummaryBar();
      updateLandingPreview();
      if (typeof syncUserChartAToSynastry === 'function') {
        syncUserChartAToSynastry(false);
      }
      if (typeof updateSynastryPredictSourceBanner === 'function') {
        updateSynastryPredictSourceBanner();
      }

      // Measure calculation duration
      const tEnd = (typeof performance !== 'undefined') ? performance.now() : Date.now();
      const duration = (tEnd - tStart).toFixed(2);
      const perfBadge = document.getElementById('calcPerfBadge');
      if (perfBadge) {
        perfBadge.textContent = (currentLang === 'en') ? `⚡ Instant Calculation (${duration}ms)` : `⚡ 瞬时计算完成 (${duration}ms)`;
      }
    } catch (err) {
      if (typeof console !== 'undefined' && console.error) console.error('排盘计算发生异常:', err);
    }
  }

  // Render Four Pillars & Statistics
  function renderChart(res) {
    const isEn = (currentLang === 'en');
    const pillars = ['year', 'month', 'day', 'hour'];
    const titles = [0, 1, 2, 3].map(i => (typeof I18N !== 'undefined' ? I18N.getPillarTitle(i, currentLang) : ['年柱 (根基/祖业)', '月柱 (提纲/事业)', '日柱 (日元/自身)', '时柱 (归宿/子女)'][i]));

    const container = document.getElementById('pillarsContainer');
    container.innerHTML = '';
    const shenShaData = (typeof BaZiEngine !== 'undefined' && typeof BaZiEngine.calculateShenSha === 'function')
      ? BaZiEngine.calculateShenSha(res, currentLang)
      : null;

    pillars.forEach((pKey, idx) => {
      const p = res.pillars[pKey];
      const isDayMaster = (pKey === 'day');

      const card = document.createElement('div');
      card.className = `pillar-card p-4 flex flex-col items-center justify-between ${isDayMaster ? 'border-amber-500/60 shadow-amber-900/20' : ''}`;

      // Hidden stems HTML
      const hiddenHtml = p.hidden.map(h => `
        <div class="flex items-center justify-between text-xs py-0.5 border-b border-gray-700/30">
          <span class="font-bold ${getElementClass(h.element)}">${h.stem} (${typeof I18N !== 'undefined' ? I18N.getElement(h.element, currentLang) : h.element})</span>
          <span class="text-gray-400 text-[11px]">${typeof I18N !== 'undefined' ? I18N.getGod(h.god, currentLang) : h.god}</span>
          <span class="text-gray-500 text-[10px]">${Math.round(h.weight * 100)}%</span>
        </div>
      `).join('');

      const godDisplay = isDayMaster 
        ? (isEn ? 'Day Master (Self)' : '日主') 
        : (typeof I18N !== 'undefined' ? I18N.getGod(p.stemGod, currentLang) : p.stemGod);

      const isYearPillar = (pKey === 'year');
      const zodiacText = isYearPillar && typeof I18N !== 'undefined'
        ? ` <span class="text-[10px] text-amber-300 font-mono">(${isEn ? `Zodiac: ${I18N.getZodiac(p.branch, 'en')}` : `属${I18N.getZodiac(p.branch, 'zh')}`})</span>`
        : '';

      const badges = (shenShaData && shenShaData.pillarsShenSha && shenShaData.pillarsShenSha[pKey]) || [];
      const shenShaHtml = badges.length > 0
        ? badges.map(b => `<span class="px-1.5 py-0.5 rounded text-[10px] font-bold border ${b.color}" title="${b.desc}">${b.icon} ${b.name}</span>`).join('')
        : `<span class="text-[10px] text-gray-500 py-0.5">${typeof I18N !== 'undefined' ? I18N.t('pillar_shensha_none', currentLang) : (isEn ? 'Harmonious Flow' : '气机平和')}</span>`;

      card.innerHTML = `
        <div class="w-full flex justify-between items-center mb-2 pb-1 border-b border-gray-700/40">
          <span class="text-xs text-gray-400 font-medium">${titles[idx]}${zodiacText}</span>
          <span class="pillar-badge ${isDayMaster ? 'bg-amber-500/20 text-amber-300 font-bold' : 'text-gray-300'}">
            ${godDisplay}
          </span>
        </div>

        <div class="my-3 flex flex-col items-center">
          <!-- Heavenly Stem -->
          <div class="flex items-center space-x-2 my-1">
            <span class="text-4xl font-bold font-serif-sc ${getElementClass(p.stemElement)}">
              ${p.stem}
            </span>
            <span class="text-[10px] px-1.5 py-0.5 rounded ${getElementBgClass(p.stemElement)} ${getElementClass(p.stemElement)}">
              ${typeof I18N !== 'undefined' ? I18N.getElement(p.stemElement, currentLang) : p.stemElement}
            </span>
          </div>

          <!-- Earthly Branch -->
          <div class="flex items-center space-x-2 my-1">
            <span class="text-4xl font-bold font-serif-sc ${getElementClass(p.branchElement)}">
              ${p.branch}
            </span>
            <span class="text-[10px] px-1.5 py-0.5 rounded ${getElementBgClass(p.branchElement)} ${getElementClass(p.branchElement)}">
              ${typeof I18N !== 'undefined' ? I18N.getElement(p.branchElement, currentLang) : p.branchElement}
            </span>
          </div>
        </div>

        <!-- Hidden Stems -->
        <div class="w-full bg-black/20 rounded-lg p-2.5 my-2">
          <div class="text-[11px] text-gray-400 mb-1 font-medium flex justify-between">
            <span>${typeof I18N !== 'undefined' ? I18N.t('hidden_stems_title', currentLang) : '地支藏干'}</span>
            <span>${typeof I18N !== 'undefined' ? I18N.t('hidden_stems_god', currentLang) : '十神分气'}</span>
          </div>
          ${hiddenHtml}
        </div>

        <!-- Na Yin -->
        <div class="w-full text-center mt-2 pt-2 border-t border-gray-700/30">
          <span class="text-xs text-gray-400">${typeof I18N !== 'undefined' ? I18N.t('nayin_prefix', currentLang) : '纳音：'}</span>
          <span class="text-xs font-semibold text-amber-200/90">${typeof I18N !== 'undefined' ? I18N.getNaYin(p.naYin, currentLang) : p.naYin}</span>
        </div>

        <!-- Auspicious Deities & Shen Sha Badges -->
        <div class="w-full mt-2 pt-2 border-t border-gray-700/30">
          <div class="text-[10px] text-gray-400 mb-1 font-medium flex justify-between items-center">
            <span data-i18n="pillar_shensha_title">${typeof I18N !== 'undefined' ? I18N.t('pillar_shensha_title', currentLang) : (isEn ? 'Auspicious Stars' : '吉神星煞')}</span>
            <span class="text-[9px] text-amber-400/80 font-mono" data-i18n="pillar_shensha_sub">${typeof I18N !== 'undefined' ? I18N.t('pillar_shensha_sub', currentLang) : (isEn ? 'Shen Sha' : '神煞鉴照')}</span>
          </div>
          <div class="flex flex-wrap gap-1 justify-center min-h-[22px]">
            ${shenShaHtml}
          </div>
        </div>
      `;

      container.appendChild(card);
    });

    // Update Solar Info Tag
    const solarTag = document.getElementById('solarTermTag');
    if (solarTag) {
      solarTag.textContent = isEn
        ? `Solar Term: Month ${res.solarInfo.jieName} (${res.solarInfo.monthBranch}) · Solar Year: ${res.solarInfo.solarYear}`
        : `节气令星：${res.solarInfo.jieName}月建（${res.solarInfo.monthBranch}月）· 太阳公历年：${res.solarInfo.solarYear}`;
    }

    // Update Day Master Overview
    const dmStemName = typeof I18N !== 'undefined' ? I18N.getStem(res.dayMaster, currentLang) : `${res.dayMasterYinYang}${res.dayMasterElement}`;
    document.getElementById('dmTitle').textContent = isEn
      ? `${res.dayMaster} - ${dmStemName}`
      : `${res.dayMaster} (${res.dayMasterYinYang}${res.dayMasterElement})`;
    document.getElementById('dmTitle').className = `text-2xl font-bold font-serif-sc ${getElementClass(res.dayMasterElement)}`;

    // Render Five Elements Breakdown
    const elContainer = document.getElementById('elementsBarContainer');
    elContainer.innerHTML = '';
    const elList = ['木', '火', '土', '金', '水'];
    elList.forEach(el => {
      const pct = res.elements.percentages[el] || 0;
      const score = res.elements.scores[el] ? res.elements.scores[el].toFixed(1) : '0';
      const elLabel = typeof I18N !== 'undefined' ? I18N.getElement(el, currentLang) : el;
      const row = document.createElement('div');
      row.className = 'flex items-center space-x-2 text-sm';
      row.innerHTML = `
        <span class="w-14 font-bold ${getElementClass(el)}">${elLabel}</span>
        <div class="flex-1 bg-gray-700/40 rounded-full h-2.5 overflow-hidden">
          <div class="h-full rounded-full ${getElementBgClass(el)}" style="width: ${Math.min(pct * 2, 100)}%; background-color: var(--color-${el === '木' ? 'wood' : el === '火' ? 'fire' : el === '土' ? 'earth' : el === '金' ? 'metal' : 'water'});"></div>
        </div>
        <span class="w-16 text-right text-xs text-gray-300 font-mono">${pct}% (${score})</span>
      `;
      elContainer.appendChild(row);
    });

    // Render Canvas Radar Chart
    ElementChart.renderRadar('elementRadarCanvas', res.elements.percentages);
    if (typeof VisualAlchemy !== 'undefined') {
      VisualAlchemy.setActiveElement(res.dayMasterElement || '木');
    }
    const dossierModal = document.getElementById('imperialDossierModal');
    if (typeof renderImperialDossierPages === 'function' && dossierModal && !dossierModal.classList.contains('hidden')) {
      renderImperialDossierPages(currentLang);
    }
    renderFourAuspiciousDeities(res, shenShaData);
    renderSensitivityAnalysis(res);
  }

  // Render Canonical Four Major Auspicious Deities Matrix (天乙贵人 · 文昌贵人 · 红鸾天喜 · 驿马星动)
  function renderFourAuspiciousDeities(res, precalcShenSha = null) {
    const container = document.getElementById('fourDeitiesCardsContainer');
    if (!container) return;
    const isEn = (currentLang === 'en');
    const shenSha = precalcShenSha || (typeof BaZiEngine !== 'undefined' && typeof BaZiEngine.calculateShenSha === 'function' ? BaZiEngine.calculateShenSha(res, currentLang) : null);
    if (!shenSha || !shenSha.fourAuspicious) return;

    container.innerHTML = shenSha.fourAuspicious.map(d => {
      const dName = isEn ? (d.nameEn || d.name || '') : (d.nameZh || d.name || '');
      const dVerse = isEn ? (d.verseEn || d.verse || '') : (d.verseZh || d.verse || '');
      const dEssence = isEn ? (d.essenceEn || d.essence || '') : (d.essenceZh || d.essence || '');
      const dTrigger = isEn ? (d.triggerEn || d.trigger || '') : (d.triggerZh || d.trigger || '');
      const dStatus = isEn ? (d.statusEn || d.status || '') : (d.statusZh || d.status || '');
      const dLocation = isEn ? (d.locationTextEn || d.locationText || '') : (d.locationTextZh || d.locationText || '');

      return `
      <div class="deity-card p-4 rounded-xl border border-amber-600/30 bg-[#161824]/90 hover:border-amber-500/60 transition shadow-lg flex flex-col justify-between space-y-3">
        <div>
          <!-- Header -->
          <div class="flex items-center justify-between pb-2 border-b border-gray-800">
            <div class="flex items-center space-x-2">
              <span class="text-xl">${d.icon || '✨'}</span>
              <span class="font-bold font-serif-sc text-sm text-amber-200">${dName}</span>
            </div>
            <span class="text-[10px] px-2 py-0.5 rounded-full border font-mono ${d.statusClass || ''}">
              ${dStatus}
            </span>
          </div>

          <!-- Verse -->
          <div class="mt-2.5 p-2 rounded-lg bg-black/40 border border-gray-800/80 text-[11px] text-amber-300/90 font-serif-sc leading-relaxed">
            ${dVerse}
          </div>

          <!-- Content Details -->
          <div class="mt-2.5 space-y-2 text-xs text-gray-300">
            <p>
              <span class="text-gray-400 font-medium">${typeof I18N !== 'undefined' ? I18N.t('deity_card_location_label', currentLang) : (isEn ? 'Chart Position: ' : '命盘落位：')}</span>
              <span class="font-semibold text-amber-200">${dLocation}</span>
            </p>
            <p class="text-gray-400 text-[11px] leading-relaxed">
              <span class="text-gray-300 font-medium">${typeof I18N !== 'undefined' ? I18N.t('deity_card_essence_label', currentLang) : (isEn ? 'Manifested Power: ' : '显化威能：')}</span>
              ${dEssence}
            </p>
            <p class="text-emerald-400/90 text-[11px] leading-relaxed">
              <span class="text-emerald-300 font-medium">${typeof I18N !== 'undefined' ? I18N.t('deity_card_trigger_label', currentLang) : (isEn ? 'Transit Cycle: ' : '岁运时令：')}</span>
              ${dTrigger}
            </p>
          </div>
        </div>
      </div>
    `;
    }).join('');
  }

  // Render Birth Time Sensitivity & Structural Stability (生时临界微扰分析与结构稳定性)
  function renderSensitivityAnalysis(res) {
    const section = document.getElementById('sensitivityStatusSection');
    if (!section || typeof SensitivityEngine === 'undefined') return;
    const isEn = (currentLang === 'en');
    const bDate = document.getElementById('birthDate')?.value;
    const bTime = document.getElementById('birthTime')?.value;
    if (!bDate || !bTime) return;

    const [year, month, day] = bDate.split('-').map(Number);
    const [hour, minute] = bTime.split(':').map(Number);
    const gender = document.getElementById('gender')?.value || '乾造';
    const useTrueSolarTime = document.getElementById('useTrueSolarTime')?.checked || false;
    const isLateRatNextDay = document.getElementById('lateRatNextDay')?.checked || false;
    const longitude = parseFloat(document.getElementById('customLongitude')?.value) || 116.4;
    const timezone = parseFloat(document.getElementById('timezoneSelect')?.value) || 8.0;

    const report = SensitivityEngine.analyzePerturbation({
      year, month, day, hour, minute, gender,
      useTrueSolarTime, isLateRatNextDay, longitude, timezone
    }, 15, 1);

    if (!report) return;

    const score = report.stabilityScore;
    const status = report.status;
    const badgeEl = document.getElementById('sensitivityBadge');
    const iconEl = document.getElementById('sensitivityIcon');
    const scoreLabel = document.getElementById('sensitivityScoreLabel');
    const varianceLabel = document.getElementById('sensitivityVarianceLabel');
    const progressBar = document.getElementById('sensitivityProgressBar');
    const diagnosisText = document.getElementById('sensitivityDiagnosisText');

    if (badgeEl) {
      if (status === 'robust') {
        badgeEl.className = 'text-[10px] px-2 py-0.5 rounded-full font-mono font-bold bg-emerald-950/80 text-emerald-300 border border-emerald-500/40';
        badgeEl.textContent = isEn ? `STABILITY ${score}% (ROBUST)` : `稳定性 ${score}% (刚健)`;
      } else if (status === 'moderate') {
        badgeEl.className = 'text-[10px] px-2 py-0.5 rounded-full font-mono font-bold bg-amber-950/80 text-amber-300 border border-amber-500/40';
        badgeEl.textContent = isEn ? `STABILITY ${score}% (MODERATE)` : `稳定性 ${score}% (稳固)`;
      } else {
        badgeEl.className = 'text-[10px] px-2 py-0.5 rounded-full font-mono font-bold bg-rose-950/80 text-rose-300 border border-rose-500/40 animate-pulse';
        badgeEl.textContent = isEn ? `STABILITY ${score}% (CRITICAL CUSP)` : `稳定性 ${score}% (临界相变区)`;
      }
    }

    if (iconEl) {
      iconEl.textContent = (status === 'robust') ? '🛡️' : (status === 'moderate' ? '⚖️' : '⚠️');
    }

    if (scoreLabel) {
      scoreLabel.textContent = isEn
        ? `Structural Stability Score: ${score}%`
        : `结构稳定性得分: ${score}%`;
    }

    if (varianceLabel) {
      varianceLabel.textContent = isEn
        ? `Vigor Variance: ${report.variance.toFixed(2)} | Range: ${report.scoreRange.toFixed(1)} pts`
        : `旺衰方差: ${report.variance.toFixed(2)} | 极差: ${report.scoreRange.toFixed(1)} 分`;
    }

    if (progressBar) {
      progressBar.style.width = `${score}%`;
      if (status === 'robust') {
        progressBar.className = 'h-full bg-gradient-to-r from-emerald-500 to-teal-400 transition-all duration-500';
      } else if (status === 'moderate') {
        progressBar.className = 'h-full bg-gradient-to-r from-amber-500 to-yellow-400 transition-all duration-500';
      } else {
        progressBar.className = 'h-full bg-gradient-to-r from-rose-500 to-orange-500 transition-all duration-500';
      }
    }

    if (diagnosisText) {
      diagnosisText.textContent = isEn ? report.messageEn : report.messageZh;
    }
  }

  // Initialize Rectification Modal Lifecycle & Event Listeners
  function initRectificationModal() {
    const modal = document.getElementById('rectificationModal');
    const openBtn1 = document.getElementById('btnOpenRectificationModal');
    const openBtn2 = document.getElementById('btnTriggerRectificationFromCard');
    const openBtnTop = document.getElementById('btnRectifyTopNav');
    const openBtnBanner = document.getElementById('btnBannerOpenRectification');
    const openBtnNav = document.getElementById('navBtnRectification');
    const openBtnPortal = document.getElementById('portalFeatureRectify');
    const closeBtn = document.getElementById('rectificationCloseBtn');
    const runBtn = document.getElementById('btnRunRectification');
    const loadSampleBtn = document.getElementById('btnLoadSampleEvents');

    function openModal() {
      if (!modal) return;
      const bDate = document.getElementById('birthDate')?.value;
      const bGender = document.getElementById('gender')?.value;
      const rDate = document.getElementById('rectifyBirthDate');
      const rGender = document.getElementById('rectifyGender');
      if (rDate && bDate) rDate.value = bDate;
      if (rGender && bGender) rGender.value = bGender;
      modal.classList.remove('hidden');
    }

    function closeModal() {
      if (!modal) return;
      modal.classList.add('hidden');
    }

    if (openBtn1) openBtn1.addEventListener('click', openModal);
    if (openBtn2) openBtn2.addEventListener('click', openModal);
    if (openBtnTop) openBtnTop.addEventListener('click', openModal);
    if (openBtnBanner) openBtnBanner.addEventListener('click', openModal);
    if (openBtnNav) openBtnNav.addEventListener('click', openModal);
    if (openBtnPortal) openBtnPortal.addEventListener('click', openModal);
    if (closeBtn) closeBtn.addEventListener('click', closeModal);
    if (runBtn) runBtn.addEventListener('click', handleRunRectification);

    if (loadSampleBtn) {
      loadSampleBtn.addEventListener('click', () => {
        const isEn = (currentLang === 'en');
        const y1 = document.getElementById('rectifyEventYear1');
        const t1 = document.getElementById('rectifyEventType1');
        const d1 = document.getElementById('rectifyEventDesc1');
        if (y1) y1.value = '2018';
        if (t1) t1.value = 'career_academic';
        if (d1) d1.value = isEn ? 'College Entrance / University Admission' : '高考考研 / 名校录取';

        const y2 = document.getElementById('rectifyEventYear2');
        const t2 = document.getElementById('rectifyEventType2');
        const d2 = document.getElementById('rectifyEventDesc2');
        if (y2) y2.value = '2022';
        if (t2) t2.value = 'career_academic';
        if (d2) d2.value = isEn ? 'Major Career Promotion / Landed Tech Giant' : '职场跃迁 / 入职大厂';

        const y3 = document.getElementById('rectifyEventYear3');
        const t3 = document.getElementById('rectifyEventType3');
        const d3 = document.getElementById('rectifyEventDesc3');
        if (y3) y3.value = '2024';
        if (t3) t3.value = 'relocation_travel';
        if (d3) d3.value = isEn ? 'Cross-City Relocation / Rental Move' : '跨城迁移 / 独立租房';

        handleRunRectification();
      });
    }
  }

  // Run Bayesian Birth Time Rectification
  function handleRunRectification() {
    if (typeof RectificationEngine === 'undefined') return;
    const isEn = (currentLang === 'en');
    const rDate = document.getElementById('rectifyBirthDate')?.value || document.getElementById('birthDate')?.value;
    if (!rDate) {
      alert(isEn ? 'Please confirm birth date first.' : '请先确认出生日期。');
      return;
    }
    const [year, month, day] = rDate.split('-').map(Number);
    const gender = document.getElementById('rectifyGender')?.value || '乾造';
    const approxVal = parseInt(document.getElementById('rectifyApproxHour')?.value, 10);

    const events = [];
    const y1 = parseInt(document.getElementById('rectifyEventYear1')?.value, 10);
    const t1 = document.getElementById('rectifyEventType1')?.value;
    const d1 = document.getElementById('rectifyEventDesc1')?.value || '';
    if (y1 && t1) events.push({ year: y1, type: t1, description: d1 });

    const y2 = parseInt(document.getElementById('rectifyEventYear2')?.value, 10);
    const t2 = document.getElementById('rectifyEventType2')?.value;
    const d2 = document.getElementById('rectifyEventDesc2')?.value || '';
    if (y2 && t2) events.push({ year: y2, type: t2, description: d2 });

    const y3 = parseInt(document.getElementById('rectifyEventYear3')?.value, 10);
    const t3 = document.getElementById('rectifyEventType3')?.value;
    const d3 = document.getElementById('rectifyEventDesc3')?.value || '';
    if (y3 && t3) events.push({ year: y3, type: t3, description: d3 });

    if (events.length === 0) {
      alert(isEn ? 'Please enter at least 1 or 2 past major historical life events.' : '请至少录入 1~2 个已发生的确定性重大历史事件。');
      return;
    }

    const useTrueSolarTime = document.getElementById('useTrueSolarTime')?.checked || false;
    const longitude = parseFloat(document.getElementById('customLongitude')?.value) || 116.4;
    const timezone = parseFloat(document.getElementById('timezoneSelect')?.value) || 8.0;

    const natalBase = {
      year, month, day, gender,
      approximateHour: (!isNaN(approxVal) && approxVal >= 0) ? approxVal : null,
      useTrueSolarTime, longitude, timezone
    };

    const res = RectificationEngine.rectifyBirthTime(natalBase, events);
    if (!res || !res.top1) return;

    renderRectificationResults(res, isEn);
  }

  // Render Bayesian MAP Rectification Results & Rankings
  function renderRectificationResults(res, isEn) {
    const resultsArea = document.getElementById('rectificationResultsArea');
    if (!resultsArea) return;
    resultsArea.classList.remove('hidden');

    const top1 = res.top1;
    const top2 = res.top2;
    const tie = res.tieBreaker;

    let tieBreakerHtml = '';
    if (tie) {
      tieBreakerHtml = `
        <div class="p-3.5 rounded-xl bg-gradient-to-r from-amber-950/60 to-purple-950/60 border border-amber-500/60 shadow-lg space-y-2">
          <div class="flex items-center justify-between">
            <span class="text-xs font-bold text-amber-300 flex items-center gap-1.5 font-serif-sc">
              <span>⚖️</span>
              <span>${isEn ? tie.titleEn : tie.titleZh}</span>
            </span>
            <span class="text-[9px] px-1.5 py-0.5 rounded bg-amber-900 text-amber-200 font-mono">TIE-BREAKER</span>
          </div>
          <p class="text-xs text-amber-100/90 leading-relaxed font-sans">
            ${isEn ? tie.questionEn : tie.questionZh}
          </p>
          <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 pt-1">
            <button type="button" class="btn-tiebreaker-choice text-left p-2.5 rounded-lg border border-amber-600/40 bg-black/40 hover:bg-amber-900/40 hover:border-amber-400 transition cursor-pointer active:scale-95" data-cand-idx="0">
              <div class="text-xs font-bold text-amber-200 mb-0.5">${isEn ? tie.optionAEn : tie.optionAZh}</div>
              <div class="text-[10px] text-gray-400 font-mono">${isEn ? 'Confirm & Apply' : '确认为此并排盘'} ➔ ${isEn ? top1.nameEn : top1.nameZh}</div>
            </button>
            <button type="button" class="btn-tiebreaker-choice text-left p-2.5 rounded-lg border border-purple-600/40 bg-black/40 hover:bg-purple-900/40 hover:border-purple-400 transition cursor-pointer active:scale-95" data-cand-idx="1">
              <div class="text-xs font-bold text-purple-200 mb-0.5">${isEn ? tie.optionBEn : tie.optionBZh}</div>
              <div class="text-[10px] text-gray-400 font-mono">${isEn ? 'Confirm & Apply' : '确认为此并排盘'} ➔ ${isEn ? (top2 ? (isEn ? top2.nameEn : top2.nameZh) : '') : ''}</div>
            </button>
          </div>
        </div>
      `;
    }

    const evidencesHtml = (top1.evidences || []).map(ev => `
      <div class="flex items-start gap-1.5 text-[11px] text-emerald-200/90">
        <span class="text-emerald-400 font-bold">✓</span>
        <span>${isEn ? ev.textEn : ev.textZh}</span>
      </div>
    `).join('');

    const rankingsHtml = (res.rankings || []).slice(0, 5).map((c, i) => `
      <div class="flex items-center justify-between p-2 rounded-lg bg-black/30 border border-gray-800 text-xs">
        <div class="flex items-center gap-2">
          <span class="w-5 text-center font-mono font-bold ${i === 0 ? 'text-amber-400' : 'text-gray-500'}">#${i + 1}</span>
          <span class="font-medium text-gray-200">${isEn ? c.nameEn : c.nameZh}</span>
          <span class="text-[10px] px-1.5 py-0.2 rounded bg-gray-800 text-gray-400 font-mono">${isEn ? c.hourPillarEn : c.hourPillarZh}</span>
        </div>
        <div class="flex items-center gap-2">
          <div class="w-20 sm:w-28 bg-gray-800 h-1.5 rounded-full overflow-hidden">
            <div class="h-full bg-gradient-to-r from-amber-500 to-emerald-400" style="width: ${c.confidencePercent}%;"></div>
          </div>
          <span class="font-mono text-[11px] text-amber-300 w-10 text-right">${c.confidencePercent}%</span>
        </div>
      </div>
    `).join('');

    resultsArea.innerHTML = `
      <!-- Winner Candidate Card -->
      <div class="p-4 rounded-xl border border-emerald-500/60 bg-gradient-to-r from-emerald-950/40 via-black/40 to-emerald-950/40 shadow-xl space-y-3">
        <div class="flex items-center justify-between border-b border-emerald-800/40 pb-2">
          <div>
            <div class="text-[10px] font-bold text-emerald-400 font-mono tracking-wider">${isEn ? 'MAXIMUM A POSTERIORI (MAP) CANDIDATE' : '贝叶斯最大后验概率推荐时辰'}</div>
            <h4 class="text-base font-bold text-gray-100 font-serif-sc mt-0.5">${isEn ? top1.nameEn : top1.nameZh} · ${isEn ? top1.hourPillarEn : top1.hourPillarZh}${isEn ? ' Pillar' : '柱'}</h4>
          </div>
          <div class="text-right">
            <div class="text-2xl font-black text-emerald-400 font-mono">${top1.confidencePercent}%</div>
            <div class="text-[10px] text-gray-400 font-mono">${isEn ? 'Confidence' : '后验置信度'}</div>
          </div>
        </div>

        <div class="space-y-1.5">
          <div class="text-[11px] font-bold text-gray-300 font-serif-sc">${isEn ? 'Deterministic Historical Evidence Alignment:' : '重大历史事件对数似然增益印证：'}</div>
          <div class="space-y-1 bg-black/30 p-2 rounded-lg border border-emerald-900/30">
            ${evidencesHtml || `<div class="text-gray-400 text-xs">${isEn ? 'Aligned with prior distribution and static structure.' : '与先验时空分布及静态格局高度吻合。'}</div>`}
          </div>
        </div>

        <button id="btnAdoptRectifiedHour" type="button" class="w-full py-2.5 rounded-xl bg-gradient-to-r from-emerald-600 via-emerald-700 to-teal-800 hover:from-emerald-500 hover:to-teal-700 text-white font-bold text-xs shadow-lg transition flex items-center justify-center gap-2 cursor-pointer active:scale-95">
          <span>🎯</span>
          <span>${isEn ? 'Apply Recommended Hour & Recalculate Chart' : '一键采纳此推荐时辰并排盘'}</span>
        </button>
      </div>

      <!-- Tie-Breaker if bimodal -->
      ${tieBreakerHtml}

      <!-- Top Rankings -->
      <div class="p-3.5 rounded-xl bg-black/40 border border-gray-800 space-y-2">
        <div class="flex items-center justify-between text-xs font-bold text-gray-300">
          <span>${isEn ? 'Top Hypothesis Probability Spectrum' : '全时辰后验概率波谱排行榜'}</span>
          <span class="text-[10px] text-gray-500 font-mono">SOFTMAX DISTRIBUTION</span>
        </div>
        <div class="space-y-1.5">
          ${rankingsHtml}
        </div>
      </div>
    `;

    function applyHourAndRecalculate(cand) {
      if (!cand) return;
      const bTime = document.getElementById('birthTime');
      const bDate = document.getElementById('birthDate');
      const rDate = document.getElementById('rectifyBirthDate');
      if (bTime) {
        const hh = String(cand.hour).padStart(2, '0');
        const mm = String(cand.minute).padStart(2, '0');
        bTime.value = `${hh}:${mm}`;
      }
      if (bDate && rDate && rDate.value) {
        bDate.value = rDate.value;
      }
      const modal = document.getElementById('rectificationModal');
      if (modal) modal.classList.add('hidden');

      if (typeof triggerCalculate === 'function') triggerCalculate();
      const container = document.getElementById('pillarsContainer');
      if (container && typeof container.scrollIntoView === 'function') {
        container.scrollIntoView({ behavior: 'smooth' });
      }
    }

    const btnAdopt = document.getElementById('btnAdoptRectifiedHour');
    if (btnAdopt) {
      btnAdopt.addEventListener('click', () => applyHourAndRecalculate(top1));
    }

    resultsArea.querySelectorAll('.btn-tiebreaker-choice').forEach(btn => {
      btn.addEventListener('click', () => {
        const cIdx = parseInt(btn.getAttribute('data-cand-idx'), 10);
        const chosen = (cIdx === 1 && top2) ? top2 : top1;
        applyHourAndRecalculate(chosen);
      });
    });
  }

  // Initialize In-Page Bayesian Rectification Workbench
  function initInPageRectification() {
    const section = document.getElementById('rectificationSection');
    const workbench = document.getElementById('homeRectificationWorkbench');
    const toggleBtn = document.getElementById('btnToggleHomeRectification');
    const iconToggle = document.getElementById('iconToggleHomeRectify');
    const textToggle = document.getElementById('textToggleHomeRectify');
    const loadSampleBtn = document.getElementById('btnHomeLoadSampleEvents');
    const runBtn = document.getElementById('btnHomeRunRectification');

    function syncBaseFromHome() {
      const bDate = document.getElementById('birthDate')?.value;
      const bGender = document.getElementById('gender')?.value;
      const rDate = document.getElementById('homeRectifyBirthDate');
      const rGender = document.getElementById('homeRectifyGender');
      if (rDate && bDate && !rDate.value) rDate.value = bDate;
      if (rGender && bGender) rGender.value = bGender;
    }

    function toggleWorkbench(forceOpen = null) {
      if (!workbench) return;
      syncBaseFromHome();
      const shouldOpen = (forceOpen !== null) ? forceOpen : workbench.classList.contains('hidden');
      const isEn = (currentLang === 'en');
      if (shouldOpen) {
        workbench.classList.remove('hidden');
        if (iconToggle) iconToggle.textContent = '▼';
        if (textToggle) {
          textToggle.textContent = isEn ? 'Collapse Calibration Workbench' : '收起校对工作台';
          textToggle.setAttribute('data-i18n', 'btn_toggle_rectify_workbench_collapse');
        }
      } else {
        workbench.classList.add('hidden');
        if (iconToggle) iconToggle.textContent = '⚡';
        if (textToggle) {
          textToggle.textContent = isEn ? 'Expand Calibration Workbench' : '展开校对工作台';
          textToggle.setAttribute('data-i18n', 'btn_toggle_rectify_workbench');
        }
      }
    }

    if (toggleBtn) {
      toggleBtn.addEventListener('click', () => toggleWorkbench());
    }

    if (loadSampleBtn) {
      loadSampleBtn.addEventListener('click', () => {
        const isEn = (currentLang === 'en');
        const y1 = document.getElementById('homeRectifyEventYear1');
        const t1 = document.getElementById('homeRectifyEventType1');
        const d1 = document.getElementById('homeRectifyEventDesc1');
        if (y1) y1.value = '2018';
        if (t1) t1.value = 'exam';
        if (d1) d1.value = isEn ? 'National Exam / Key University Admission' : '高考金榜 / 985名校录取';

        const y2 = document.getElementById('homeRectifyEventYear2');
        const t2 = document.getElementById('homeRectifyEventType2');
        const d2 = document.getElementById('homeRectifyEventDesc2');
        if (y2) y2.value = '2021';
        if (t2) t2.value = 'career_jump';
        if (d2) d2.value = isEn ? 'Major Promotion / Joined Industry Leader' : '职场跃迁 / 破格升任总监';

        const y3 = document.getElementById('homeRectifyEventYear3');
        const t3 = document.getElementById('homeRectifyEventType3');
        const d3 = document.getElementById('homeRectifyEventDesc3');
        if (y3) y3.value = '2023';
        if (t3) t3.value = 'marriage';
        if (d3) d3.value = isEn ? 'Marriage / Acquired Home & Settled' : '领证结婚 / 置业安居';

        handleHomeRunRectification();
      });
    }

    if (runBtn) {
      runBtn.addEventListener('click', handleHomeRunRectification);
    }

    // Connect any 'btn-goto-rectification' or card rectification triggers to smoothly scroll and expand
    document.querySelectorAll('.btn-goto-rectification').forEach(btn => {
      btn.addEventListener('click', () => {
        toggleWorkbench(true);
        if (section && typeof section.scrollIntoView === 'function') {
          section.scrollIntoView({ behavior: 'smooth' });
        }
      });
    });

    const triggerFromCard = document.getElementById('btnTriggerRectificationFromCard');
    if (triggerFromCard) {
      triggerFromCard.addEventListener('click', () => {
        toggleWorkbench(true);
        if (section && typeof section.scrollIntoView === 'function') {
          section.scrollIntoView({ behavior: 'smooth' });
        }
      });
    }
  }

  // Run In-Page Bayesian Birth Time Rectification
  function handleHomeRunRectification() {
    if (typeof RectificationEngine === 'undefined') return;
    const isEn = (currentLang === 'en');
    const rDate = document.getElementById('homeRectifyBirthDate')?.value || document.getElementById('birthDate')?.value;
    if (!rDate) {
      alert(isEn ? 'Please confirm birth date first.' : '请先确认出生日期。');
      return;
    }
    const [year, month, day] = rDate.split('-').map(Number);
    const gender = document.getElementById('homeRectifyGender')?.value || document.getElementById('gender')?.value || '乾造';
    
    let approxVal = parseInt(document.getElementById('homeRectifyApproxHour')?.value, 10);
    if (isNaN(approxVal)) {
      const valStr = document.getElementById('homeRectifyApproxHour')?.value;
      if (valStr === 'morning') approxVal = 8;
      else if (valStr === 'afternoon') approxVal = 14;
      else if (valStr === 'evening') approxVal = 20;
      else if (valStr === 'night') approxVal = 2;
      else approxVal = -1;
    }

    const events = [];
    const y1 = parseInt(document.getElementById('homeRectifyEventYear1')?.value, 10);
    const t1 = document.getElementById('homeRectifyEventType1')?.value;
    const d1 = document.getElementById('homeRectifyEventDesc1')?.value || '';
    if (y1 && t1) events.push({ year: y1, type: t1, description: d1 });

    const y2 = parseInt(document.getElementById('homeRectifyEventYear2')?.value, 10);
    const t2 = document.getElementById('homeRectifyEventType2')?.value;
    const d2 = document.getElementById('homeRectifyEventDesc2')?.value || '';
    if (y2 && t2) events.push({ year: y2, type: t2, description: d2 });

    const y3 = parseInt(document.getElementById('homeRectifyEventYear3')?.value, 10);
    const t3 = document.getElementById('homeRectifyEventType3')?.value;
    const d3 = document.getElementById('homeRectifyEventDesc3')?.value || '';
    if (y3 && t3) events.push({ year: y3, type: t3, description: d3 });

    if (events.length === 0) {
      alert(isEn ? 'Please enter at least 1 or 2 past major historical life events.' : '请至少录入 1~2 个已发生的确定性重大历史事件。');
      return;
    }

    const useTrueSolarTime = document.getElementById('useTrueSolarTime')?.checked || false;
    const longitude = parseFloat(document.getElementById('customLongitude')?.value) || 116.4;
    const timezone = parseFloat(document.getElementById('timezoneSelect')?.value) || 8.0;

    const natalBase = {
      year, month, day, gender,
      approximateHour: (!isNaN(approxVal) && approxVal >= 0) ? approxVal : null,
      useTrueSolarTime, longitude, timezone
    };

    const res = RectificationEngine.rectifyBirthTime(natalBase, events);
    if (!res || !res.top1) return;

    renderHomeRectificationResults(res, isEn);
  }

