            <div class="p-2.5 rounded-lg bg-black/50 border border-gray-800 text-[10.5px] font-mono ${zn.isMutated ? 'text-amber-300' : 'text-emerald-300'}">
              ${isEn ? zn.ruleInteractionEn : zn.ruleInteractionZh}
            </div>
