  // ==========================================================================
  // 🌀 动力学相空间与双井势能流形 (Phase Portrait & Potential Manifold)
  // ==========================================================================
  let cachedPhaseEngine = null;
  let cachedPhaseDerived = null;

  function renderPhasePortrait(res, luckRes) {
    if (!res || typeof PhasePortraitEngine === 'undefined') return;
    const canvas = document.getElementById('phasePortraitCanvas');
    if (!canvas) return;

    if (!cachedPhaseEngine) {
      cachedPhaseEngine = new PhasePortraitEngine(canvas);
    }

    const luckCycles = (luckRes && luckRes.decades) || (res._luckDecades) || [];
    const currentAge = fourPillarsActiveAge || 30;
    const derived = PhasePortraitEngine.deriveParametersAndTrajectory(res, luckCycles, currentAge);
    cachedPhaseDerived = derived;

    const inputA = document.getElementById('paramA');
    const inputB = document.getElementById('paramB');
    const inputC = document.getElementById('paramC');
    const inputGamma = document.getElementById('paramGamma');
    const lblA = document.getElementById('labelParamA');
    const lblB = document.getElementById('labelParamB');
    const lblC = document.getElementById('labelParamC');
    const lblGamma = document.getElementById('labelParamGamma');
    const summaryBox = document.getElementById('phaseTrajectorySummary');

    if (inputA) inputA.value = derived.a;
    if (inputB) inputB.value = derived.b;
    if (inputC) inputC.value = derived.c;
    if (inputGamma) inputGamma.value = derived.gamma;

    if (lblA) lblA.textContent = derived.a.toFixed(2);
    if (lblB) lblB.textContent = derived.b.toFixed(2);
    if (lblC) lblC.textContent = derived.c.toFixed(2);
    if (lblGamma) lblGamma.textContent = derived.gamma.toFixed(2);

    const isEn = (currentLang === 'en');
    if (summaryBox) {
      summaryBox.textContent = isEn ? derived.summaryEn : derived.summaryZh;
    }

    const isDark = (typeof document !== 'undefined' && document.body && document.body.classList && typeof document.body.classList.contains === 'function')
      ? !document.body.classList.contains('light-theme')
      : true;
    cachedPhaseEngine.renderVectorField(derived.a, derived.b, derived.c, derived.gamma, isDark);
    cachedPhaseEngine.renderTrajectory(derived.trajectoryPoints, currentAge, isDark);
  }

  function initPhasePortraitControls() {
    const canvas = document.getElementById('phasePortraitCanvas');
    const inputA = document.getElementById('paramA');
    const inputB = document.getElementById('paramB');
    const inputC = document.getElementById('paramC');
    const inputGamma = document.getElementById('paramGamma');
    const lblA = document.getElementById('labelParamA');
    const lblB = document.getElementById('labelParamB');
    const lblC = document.getElementById('labelParamC');
    const lblGamma = document.getElementById('labelParamGamma');
    const btnReset = document.getElementById('btnResetPhaseParams');

    function updateFromSliders() {
      if (!canvas || typeof PhasePortraitEngine === 'undefined') return;
      if (!cachedPhaseEngine) cachedPhaseEngine = new PhasePortraitEngine(canvas);

      const a = parseFloat(inputA?.value || 1.2);
      const b = parseFloat(inputB?.value || 0.8);
      const c = parseFloat(inputC?.value || 0.0);
      const gamma = parseFloat(inputGamma?.value || 0.38);

      if (lblA) lblA.textContent = a.toFixed(2);
      if (lblB) lblB.textContent = b.toFixed(2);
      if (lblC) lblC.textContent = c.toFixed(2);
      if (lblGamma) lblGamma.textContent = gamma.toFixed(2);

      const isDark = (typeof document !== 'undefined' && document.body && document.body.classList && typeof document.body.classList.contains === 'function')
        ? !document.body.classList.contains('light-theme')
        : true;
      cachedPhaseEngine.renderVectorField(a, b, c, gamma, isDark);

      const score100 = (currentBaziResult && currentBaziResult.zipingScore && typeof currentBaziResult.zipingScore.totalScore === 'number')
        ? currentBaziResult.zipingScore.totalScore : 50.0;
      const luckCycles = (currentLuckResult && currentLuckResult.decades) || (currentBaziResult && currentBaziResult._luckDecades) || [];
      const dynamicTrajectory = PhasePortraitEngine.integrateTrajectory(a, b, c, gamma, score100, luckCycles);
      const curAge = fourPillarsActiveAge || 30;
      cachedPhaseEngine.renderTrajectory(dynamicTrajectory, curAge, isDark);

      const summaryBox = document.getElementById('phaseTrajectorySummary');
      if (summaryBox) {
        const curPt = dynamicTrajectory.find(p => p.age === curAge) || dynamicTrajectory[29];
        const isAsc = curPt.v >= 0;
        const isEn = (currentLang === 'en');
        summaryBox.textContent = isEn
          ? `System rigidity a=${a.toFixed(2)}, bifurcation b=${b.toFixed(2)}, transit bias c=${c.toFixed(2)}. Current age ${curAge} is in [${isAsc ? 'Spiral Ascending Phase' : 'Consolidation & Grounding Phase'}] (x=${curPt.x}, v=${curPt.v}).`
          : `系统刚度 a=${a.toFixed(2)}，双稳态分岔 b=${b.toFixed(2)}，岁运外场 c=${c.toFixed(2)}。命主当前 ${curAge}岁，处于【${isAsc ? '螺旋上升跃迁期 🔺' : '筑底蓄势修整期 🔻'}】(x=${curPt.x}, v=${curPt.v})。`;
      }
    }

    [inputA, inputB, inputC, inputGamma].forEach(slider => {
      if (slider) slider.addEventListener('input', updateFromSliders);
    });

    if (btnReset) {
      btnReset.addEventListener('click', () => {
        if (currentBaziResult) {
          renderPhasePortrait(currentBaziResult, currentLuckResult);
        }
      });
    }
  }

  // ==========================================================================
  // 📅 天机·个人进退节律历 (Tianji Battle Rhythm Calendar · RFC 5545)
  // ==========================================================================
  let cachedTianjiEvents = null;
  let activeTianjiFilter = 'all';

  function ensureTianjiCalendarPlacement(targetViewId) {
    const calendarEl = document.getElementById('tianjiCalendarFeedSection');
    if (!calendarEl) return;
    if (targetViewId === 'view-master-profile') {
      const chronoSec = document.getElementById('masterProfileChronoSection');
      if (chronoSec && chronoSec.parentNode && calendarEl.nextSibling !== chronoSec) {
        chronoSec.parentNode.insertBefore(calendarEl, chronoSec);
      }
    } else if (targetViewId === 'view-luck') {
      const luckSec = document.getElementById('luckCyclesSection');
      if (luckSec && luckSec.parentNode && calendarEl.nextSibling !== luckSec) {
        luckSec.parentNode.insertBefore(calendarEl, luckSec);
      }
    }
  }

  function renderTianjiCalendarFeed(res, luckRes) {
    if (typeof CalendarFeedEngine === 'undefined') return;
    const isEn = (currentLang === 'en');
    const container = document.getElementById('tianjiEventsList');
    const btnDownload = document.getElementById('btnDownloadTianjiICS');
    const btnCopyWebcal = document.getElementById('btnCopyWebcalUrl');
    if (!container) return;

    const year = selectedAnnualYear || 2026;
    const feedEngine = new CalendarFeedEngine(res, year);
    const events = feedEngine.extractCriticalEvents(year, currentLang);
    cachedTianjiEvents = events;

    // 1. Calculate dynamic category counts
    const totalCount = events.length;
    const offensiveCount = events.filter(e => e.category === 'offensive').length;
    const defensiveCount = events.filter(e => e.category === 'defensive').length;
    const wisdomCount = events.filter(e => e.category === 'wisdom').length;
    const wealthCount = events.filter(e => e.category === 'wealth').length;
    const wisdomWealthCount = wisdomCount + wealthCount;

    // 2. Update KPI Stat Badges
    const elTotal = document.getElementById('feedStatTotal');
    const elOff = document.getElementById('feedStatOffensive');
    const elDef = document.getElementById('feedStatDefensive');
    const elWW = document.getElementById('feedStatWisdomWealth');
    if (elTotal) elTotal.textContent = totalCount;
    if (elOff) elOff.textContent = offensiveCount;
    if (elDef) elDef.textContent = defensiveCount;
    if (elWW) elWW.textContent = wisdomWealthCount;

    // 3. Update Category Filter Tab Counter Badges
    const elCountAll = document.getElementById('tianjiCountAll');
    const elCountOff = document.getElementById('tianjiCountOffensive');
    const elCountDef = document.getElementById('tianjiCountDefensive');
    const elCountWisdom = document.getElementById('tianjiCountWisdom');
    const elCountWealth = document.getElementById('tianjiCountWealth');
    if (elCountAll) elCountAll.textContent = totalCount;
    if (elCountOff) elCountOff.textContent = offensiveCount;
    if (elCountDef) elCountDef.textContent = defensiveCount;
    if (elCountWisdom) elCountWisdom.textContent = wisdomCount;
    if (elCountWealth) elCountWealth.textContent = wealthCount;

    // 4. Type badge configuration helper
    const typeBadge = (type, cat) => {
      switch(type) {
        case 'crisis_defense':
          return { text: isEn ? 'Double Clash' : '天克地冲', cls: 'bg-rose-950/80 text-rose-300 border-rose-500/50' };
        case 'harmony_union':
          return { text: isEn ? 'Double Harmony' : '天地德合', cls: 'bg-emerald-950/80 text-emerald-300 border-emerald-500/50' };
        case 'blade_clash':
          return { text: isEn ? 'Blade Clash' : '羊刃逢冲', cls: 'bg-red-950/80 text-red-300 border-red-500/50' };
        case 'noble_mentor':
          return { text: isEn ? 'Noble Mentor' : '天乙贵人', cls: 'bg-indigo-950/80 text-indigo-300 border-indigo-500/50' };
        case 'wenchang_focus':
          return { text: isEn ? 'Wen Chang' : '文昌贵人', cls: 'bg-purple-950/80 text-purple-300 border-purple-500/50' };
        case 'wealth_triad':
        case 'wealth_pivot':
          return { text: isEn ? 'Wealth Triad' : '三合财局', cls: 'bg-amber-950/80 text-amber-300 border-amber-500/50' };
        case 'yima_surge':
          return { text: isEn ? 'Post Horse' : '驿马星动', cls: 'bg-cyan-950/80 text-cyan-300 border-cyan-500/50' };
        case 'solar_shift':
          return { text: isEn ? 'Solar Pivot' : '节气交节', cls: 'bg-blue-950/80 text-blue-300 border-blue-500/50' };
        default:
          return { text: isEn ? 'Strategic Pivot' : '战略拐点', cls: 'bg-gray-800 text-gray-300 border-gray-600' };
      }
    };

    // 5. Extract Top 3 Offensive Breakthroughs & Top 3 Defensive Fortresses (置于最前)
    const offensiveEvents = events.filter(e => e.category === 'offensive');
    offensiveEvents.sort((a, b) => {
      const wDiff = (b.weight || 0) - (a.weight || 0);
      if (wDiff !== 0) return wDiff;
      return (a.month * 100 + a.day) - (b.month * 100 + b.day);
    });
    const top3Offensive = offensiveEvents.slice(0, 3);

    const defensiveEvents = events.filter(e => e.category === 'defensive');
    defensiveEvents.sort((a, b) => {
      const wDiff = (b.weight || 0) - (a.weight || 0);
      if (wDiff !== 0) return wDiff;
      return (a.month * 100 + a.day) - (b.month * 100 + b.day);
    });
    const top3Defensive = defensiveEvents.slice(0, 3);

    const renderSpotlightCard = (e, idx, isDefensive) => {
      const badge = typeBadge(e.type, e.category);
      const title = isEn ? (e.titleEn || e.title) : (e.titleZh || e.title);
      const summary = isEn ? (e.summaryEn || e.summary) : (e.summaryZh || e.summary);
      const action = isEn ? (e.actionEn || e.actionRule) : (e.actionZh || e.actionRule);
      const pillar = isEn ? (e.pillarEn || e.dayPillar) : (e.pillarZh || e.dayPillar);
      const gUrl = e.googleCalendarUrl || CalendarFeedEngine.getGoogleCalendarUrl(e, currentLang);
      const borderCls = isDefensive
        ? 'border-rose-500/50 hover:border-rose-400 bg-rose-950/20'
        : 'border-emerald-500/50 hover:border-emerald-400 bg-emerald-950/20';
      const rankLabel = isDefensive
        ? (isEn ? `#${idx + 1} Defense Fortress` : `★ 第${idx + 1}防线 · 避险关口`)
        : (isEn ? `#${idx + 1} Breakthrough` : `★ 第${idx + 1}先机 · 进取要津`);
      const rankCls = isDefensive
        ? 'bg-rose-950 text-rose-300 border-rose-500/40'
        : 'bg-emerald-950 text-emerald-300 border-emerald-500/40';

      return `
        <div class="p-3.5 rounded-xl border ${borderCls} transition space-y-2 text-xs shadow-lg bg-black/60 flex flex-col justify-between">
          <div class="space-y-1.5">
            <div class="flex items-center justify-between">
              <div class="flex items-center space-x-1.5">
                <span class="font-mono text-indigo-300 font-bold tracking-tight text-xs">${e.isoDate || e.dateStr}</span>
                <span class="text-[10px] px-1.5 py-0.5 rounded font-mono bg-gray-800 text-gray-300 border border-gray-700/60">${pillar}</span>
              </div>
              <div class="flex items-center gap-1">
                <span class="text-[9.5px] px-1.5 py-0.5 rounded font-mono border ${rankCls}">${rankLabel}</span>
                <span class="text-[9.5px] px-1.5 py-0.5 rounded border font-mono ${badge.cls}">${badge.text}</span>
              </div>
            </div>
            <h5 class="font-bold text-gray-100 font-serif-sc text-xs sm:text-sm leading-snug">${title}</h5>
            <p class="text-[11px] text-gray-400 leading-relaxed">${summary}</p>
          </div>

          <div class="pt-2 border-t border-gray-800/60 space-y-2">
            <div class="text-[11px] ${isDefensive ? 'text-rose-300 bg-rose-950/30 border-rose-900/40' : 'text-emerald-300 bg-emerald-950/30 border-emerald-900/40'} leading-tight p-2 rounded-lg border">
              <strong>${isEn ? 'Tactical Directive: ' : (isDefensive ? '避险行持：' : '战术行持：')}</strong>${action}
            </div>
            <div class="flex items-center justify-between pt-1 gap-1.5">
              <a href="${gUrl}" target="_blank" rel="noopener noreferrer" class="flex-1 text-center py-1 px-2 rounded-lg bg-gray-800/90 hover:bg-gray-700 text-indigo-300 border border-indigo-500/30 text-[10px] font-semibold transition active:scale-95 flex items-center justify-center gap-1">
                <span>📅</span>
                <span>${isEn ? 'Google Cal' : 'Google 日历'}</span>
              </a>
              <button type="button" data-event-id="${e.id}" class="btn-single-ics flex-1 text-center py-1 px-2 rounded-lg bg-indigo-950/70 hover:bg-indigo-900 text-indigo-200 border border-indigo-500/40 text-[10px] font-semibold transition cursor-pointer active:scale-95 flex items-center justify-center gap-1">
                <span>📥</span>
                <span>${isEn ? 'Add to Cal (.ics)' : '导入日历 (.ics)'}</span>
              </button>
            </div>
          </div>
        </div>
      `;
    };

    const offContainer = document.getElementById('tianjiTopOffensiveCards');
    const defContainer = document.getElementById('tianjiTopDefensiveCards');
    if (offContainer) {
      offContainer.innerHTML = top3Offensive.map((e, i) => renderSpotlightCard(e, i, false)).join('');
    }
    if (defContainer) {
      defContainer.innerHTML = top3Defensive.map((e, i) => renderSpotlightCard(e, i, true)).join('');
    }

    // Dynamic Spotlight Headings Localization
    const elSpotlightTitle = document.getElementById('tianjiSpotlightTitle');
    const elSpotlightSub = document.getElementById('tianjiSpotlightSub');
    const elTopOffHeading = document.getElementById('tianjiTopOffensiveHeading');
    const elTopDefHeading = document.getElementById('tianjiTopDefensiveHeading');
    const elFullCalSummary = document.getElementById('tianjiFullCalendarSummary');

    if (elSpotlightTitle) elSpotlightTitle.textContent = isEn
      ? '[Annual Decisive Turning Points: Top 3 Breakthroughs & Top 3 Defenses]'
      : '【全年决胜核心要津 · 3 大顺势进取窗口 ✕ 3 大防御避险关口】';

    if (elSpotlightSub) elSpotlightSub.textContent = isEn
      ? 'Algorithmically synthesized top 6 strategic inflection points from the 24-point panorama. Prioritize syncing to calendar.'
      : '从全景 24 拐点中算法提炼的最关键 6 个决胜节点，建议优先导入日历并预设闹钟提醒';

    if (elTopOffHeading) elTopOffHeading.textContent = isEn
      ? 'Top 3 Breakthrough Windows'
      : '3 大顺势进取窗口 (Top 3 Breakthroughs)';

    if (elTopDefHeading) elTopDefHeading.textContent = isEn
      ? 'Top 3 Defensive Fortresses'
      : '3 大防御避险关口 (Top 3 Defense Fortresses)';

    if (elFullCalSummary) {
      elFullCalSummary.innerHTML = isEn
        ? `<div class="flex items-center gap-2">
             <span class="text-purple-400">📖</span>
             <span class="font-bold text-gray-200 font-serif-sc">[Annual 24-Event Battle Rhythm Panorama &middot; Click to Expand Details]</span>
             <span class="text-[10px] px-2 py-0.5 rounded-full bg-indigo-900/50 text-indigo-300 font-mono">24 Inflection Points</span>
           </div>
           <span class="text-xs text-gray-400 group-open:rotate-180 transition-transform duration-200">&#9660;</span>`
        : `<div class="flex items-center gap-2">
             <span class="text-purple-400">📖</span>
             <span class="font-bold text-gray-200 font-serif-sc">【全年 24 节律全景明细 · 点击展开查看全部拐点日历】</span>
             <span class="text-[10px] px-2 py-0.5 rounded-full bg-indigo-900/50 text-indigo-300 font-mono">文昌贵人 · 财运流转 · 月度全景 (24 拐点)</span>
           </div>
           <span class="text-xs text-gray-400 group-open:rotate-180 transition-transform duration-200">&#9660;</span>`;
    }

    // Helper: Bind single-event .ics download buttons
    const bindSingleIcsButtons = (root) => {
      if (!root) return;
      root.querySelectorAll('.btn-single-ics').forEach(btn => {
        if (btn.hasAttribute('data-bound-ics')) return;
        btn.setAttribute('data-bound-ics', 'true');
        btn.addEventListener('click', () => {
          const evId = btn.getAttribute('data-event-id');
          const targetEvent = events.find(e => e.id === evId);
          if (targetEvent) {
            feedEngine.downloadSingleEventICS(targetEvent, `tianji_${targetEvent.isoDate || targetEvent.dateStr}.ics`, currentLang);
          }
        });
      });
    };

    // Bind spotlight cards ICS buttons
    bindSingleIcsButtons(document.getElementById('tianjiTopSpotlight'));

    // 6. Render Full Event Cards inside Folded Details based on Active Filter
    const renderFilteredCards = () => {
      const filtered = (activeTianjiFilter === 'all')
        ? events
        : events.filter(e => e.category === activeTianjiFilter);

      if (filtered.length === 0) {
        container.innerHTML = `
          <div class="col-span-full py-8 text-center text-gray-400 text-xs">
            ${isEn ? 'No events found in this category for the selected year.' : '当前所选类别下本年度无特定拐点日。'}
          </div>
        `;
        return;
      }

      container.innerHTML = filtered.map(e => {
        const badge = typeBadge(e.type, e.category);
        const title = isEn ? (e.titleEn || e.title) : (e.titleZh || e.title);
        const summary = isEn ? (e.summaryEn || e.summary) : (e.summaryZh || e.summary);
        const action = isEn ? (e.actionEn || e.actionRule) : (e.actionZh || e.actionRule);
        const pillar = isEn ? (e.pillarEn || e.dayPillar) : (e.pillarZh || e.dayPillar);
        const gUrl = e.googleCalendarUrl || CalendarFeedEngine.getGoogleCalendarUrl(e, currentLang);

        const cardBorderCls = (e.category === 'defensive')
          ? 'border-rose-900/40 hover:border-rose-500/70'
          : (e.category === 'offensive')
            ? 'border-emerald-900/40 hover:border-emerald-500/70'
            : (e.category === 'wisdom')
              ? 'border-purple-900/40 hover:border-purple-500/70'
              : 'border-amber-900/40 hover:border-amber-500/70';

        return `
          <div class="p-3.5 rounded-xl bg-black/50 border ${cardBorderCls} transition space-y-2 text-xs shadow-md flex flex-col justify-between group">
            <div class="space-y-1.5">
              <div class="flex items-center justify-between">
                <div class="flex items-center space-x-1.5">
                  <span class="font-mono text-indigo-300 font-bold tracking-tight">${e.isoDate || e.dateStr}</span>
                  <span class="text-[10px] px-1.5 py-0.5 rounded font-mono bg-gray-800/80 text-gray-300 border border-gray-700/60">${pillar}</span>
                </div>
                <span class="text-[10px] px-2 py-0.5 rounded border font-mono ${badge.cls}">${badge.text}</span>
              </div>
              <h5 class="font-bold text-gray-100 font-serif-sc text-xs sm:text-sm leading-snug" title="${title}">${title}</h5>
              <p class="text-[11px] text-gray-400 line-clamp-3 leading-relaxed">${summary}</p>
            </div>

            <div class="pt-2 border-t border-gray-800/60 space-y-2">
              <div class="text-[11px] text-emerald-400/90 leading-tight bg-emerald-950/20 p-2 rounded-lg border border-emerald-900/30">
                <strong class="text-emerald-300">${isEn ? 'Tactical Directive: ' : '战术行持：'}</strong>${action}
              </div>
              <div class="flex items-center justify-between pt-1 gap-1.5">
                <a href="${gUrl}" target="_blank" rel="noopener noreferrer" class="flex-1 text-center py-1 px-2 rounded-lg bg-gray-800/80 hover:bg-gray-700 text-indigo-300 border border-indigo-500/30 text-[10px] font-semibold transition active:scale-95 flex items-center justify-center gap-1">
                  <span>📅</span>
                  <span>${isEn ? 'Google Cal' : 'Google 日历'}</span>
                </a>
                <button type="button" data-event-id="${e.id}" class="btn-single-ics flex-1 text-center py-1 px-2 rounded-lg bg-indigo-950/60 hover:bg-indigo-900/60 text-indigo-200 border border-indigo-500/40 text-[10px] font-semibold transition cursor-pointer active:scale-95 flex items-center justify-center gap-1">
                  <span>📥</span>
                  <span>${isEn ? 'Add to Cal (.ics)' : '导入日历 (.ics)'}</span>
                </button>
              </div>
            </div>
          </div>
        `;
      }).join('');

      bindSingleIcsButtons(container);
    };

    // 5. Initial render of cards
    renderFilteredCards();

    // 6. Bind Category Filter Tab buttons
    const filterButtons = document.querySelectorAll('.tianji-filter-btn');
    filterButtons.forEach(btn => {
      if (btn.hasAttribute('data-bound-filter')) return;
      btn.setAttribute('data-bound-filter', 'true');
      btn.addEventListener('click', () => {
        const filter = btn.getAttribute('data-filter') || 'all';
        activeTianjiFilter = filter;

        // Update active style
        filterButtons.forEach(b => {
          const f = b.getAttribute('data-filter');
          if (f === filter) {
            b.className = 'tianji-filter-btn px-3 py-1.5 rounded-lg bg-indigo-600 text-white font-semibold shadow transition cursor-pointer';
          } else {
            b.className = 'tianji-filter-btn px-3 py-1.5 rounded-lg bg-gray-800/80 hover:bg-gray-700/80 text-gray-300 border border-gray-700 font-semibold transition cursor-pointer';
          }
        });

        renderFilteredCards();
      });
    });

    // 7. Bind Download Full Year .ics Button
    if (btnDownload && !btnDownload.hasAttribute('data-bound')) {
      btnDownload.setAttribute('data-bound', 'true');
      btnDownload.addEventListener('click', () => {
        const eng = new CalendarFeedEngine(currentBaziResult, selectedAnnualYear || 2026);
        eng.downloadICS(cachedTianjiEvents, `tianji_calendar_${selectedAnnualYear || 2026}.ics`, currentLang);
      });
    }

    // 8. Bind Copy Webcal Subscription Link Button
    if (btnCopyWebcal && !btnCopyWebcal.hasAttribute('data-bound')) {
      btnCopyWebcal.setAttribute('data-bound', 'true');
      btnCopyWebcal.addEventListener('click', () => {
        const url = CalendarFeedEngine.getWebcalSubscriptionUrl(currentBaziResult, selectedAnnualYear || 2026);
        if (navigator && navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
          navigator.clipboard.writeText(url).then(() => {
            const orig = btnCopyWebcal.innerHTML;
            btnCopyWebcal.innerHTML = `<span>✅ ${currentLang === 'en' ? 'Copied URL!' : '已复制订阅链接!'}</span>`;
            setTimeout(() => { btnCopyWebcal.innerHTML = orig; }, 2000);
          });
        } else {
          prompt(currentLang === 'en' ? 'Copy Webcal Subscription URL:' : '请复制 Webcal 订阅链接：', url);
        }
      });
    }
  }

  // ==========================================================================
  // ♟️ 组织多方博弈政治矩阵 (Political Game Network)
  // ==========================================================================
  function renderPoliticalGameMatrix(res, luckRes) {
    if (typeof PoliticalGameMatrix === 'undefined') return;
    const isEn = (currentLang === 'en');

    const meStemEl = document.getElementById('gameStemMe');
    const bossStemEl = document.getElementById('gameStemBoss');
    const rivalStemEl = document.getElementById('gameStemRival');
    const allyStemEl = document.getElementById('gameStemAlly');
    const tblContainer = document.getElementById('gameMatrixTblContainer');
    const stratCard = document.getElementById('gameTransitStrategyCard');

    if (res && res.dayMaster && meStemEl && !meStemEl.hasAttribute('data-user-selected')) {
      meStemEl.value = res.dayMaster;
    }

    const meStem = meStemEl?.value || (res && res.dayMaster) || '甲';
    const bossStem = bossStemEl?.value || '庚';
    const rivalStem = rivalStemEl?.value || '辛';
    const allyStem = allyStemEl?.value || '壬';

    const players = [
      { id: 'me', nameZh: '我 (命主)', nameEn: 'Self (Day Master)', dm: meStem, role: 'self' },
      { id: 'boss', nameZh: '直属领导 (决策者)', nameEn: 'Direct Supervisor', dm: bossStem, role: 'leader' },
      { id: 'rival', nameZh: '竞争对手 (同侪)', nameEn: 'Key Competitor (Peer)', dm: rivalStem, role: 'rival' },
      { id: 'ally', nameZh: '核心技术骨干 (潜在同盟)', nameEn: 'Core Technical Ally', dm: allyStem, role: 'ally' }
    ];

    const matrixEngine = new PoliticalGameMatrix(players);
    const matrix = matrixEngine.buildMatrix(currentLang);

    if (tblContainer) {
      let html = `<table class="w-full text-xs text-left border-collapse">`;
      html += `<thead><tr class="border-b border-indigo-900/60 text-gray-400 font-mono">`;
      html += `<th class="p-2">${isEn ? 'Actor \\ Target' : '施动方 \\ 目标方'}</th>`;
      players.forEach(p => {
        html += `<th class="p-2 text-indigo-300 font-bold">${isEn ? p.nameEn : p.nameZh} (${p.dm})</th>`;
      });
      html += `</tr></thead><tbody>`;

      matrix.forEach(row => {
        html += `<tr class="border-b border-gray-800/60 hover:bg-white/5 transition">`;
        html += `<td class="p-2 font-bold text-indigo-200">${isEn ? row.player.nameEn : row.player.nameZh} (${row.player.dm})</td>`;
        row.relations.forEach(cell => {
          if (cell.targetId === row.player.id) {
            html += `<td class="p-2 text-gray-600 font-mono text-center">—</td>`;
          } else {
            const edgeColor = cell.edgeType === 'conflict' ? 'text-rose-400 bg-rose-950/30' :
                             cell.edgeType === 'synergy' ? 'text-emerald-400 bg-emerald-950/30' :
                             cell.edgeType === 'friction' ? 'text-amber-400 bg-amber-950/30' : 'text-blue-300 bg-blue-950/30';
            html += `<td class="p-2">
              <span class="px-1.5 py-0.5 rounded text-[11px] font-semibold ${edgeColor}">
                ${isEn ? cell.tenGodEn : cell.tenGodZh}
              </span>
              <div class="text-[10px] text-gray-400 mt-1 leading-tight">${isEn ? cell.descEn : cell.descZh}</div>
            </td>`;
          }
        });
        html += `</tr>`;
      });
      html += `</tbody></table>`;
      tblContainer.innerHTML = html;
    }

    // Transit Strategy Card
    if (stratCard) {
      const transitStem = (luckRes && luckRes.annual && luckRes.annual.pillar && luckRes.annual.pillar.stem) || '丙';
      const transitReports = matrixEngine.analyzeYearTransit(transitStem, currentLang);
      
      let stratHtml = `
        <div class="flex items-center justify-between pb-2 border-b border-amber-800/40 mb-3">
          <h4 class="text-sm font-bold text-amber-200 font-serif-sc flex items-center gap-2">
            <span>📜</span>
            <span>${isEn ? 'Transit Year Political Directives (Codex Rong Ku Jian)' : '当值流年多方破局战法 (融合《荣枯鉴》)'}</span>
          </h4>
          <span class="text-[10px] font-mono text-amber-400 bg-amber-950/80 px-2 py-0.5 rounded border border-amber-700/50">
            ${isEn ? `TRANSIT STEM [${transitStem}]` : `岁君干支【${transitStem}】`}
          </span>
        </div>
        <div class="grid grid-cols-1 md:grid-cols-3 gap-3">
      `;

      transitReports.forEach(rep => {
        stratHtml += `
          <div class="p-3 rounded-lg bg-black/40 border border-amber-900/30 space-y-1.5 text-xs">
            <div class="font-bold text-amber-300 flex items-center gap-1.5">
              <span>🎯</span>
              <span>${rep.strategic_posture}</span>
            </div>
            <p class="text-gray-300 text-[11px] leading-relaxed">${rep.tactical_action}</p>
            <blockquote class="p-1.5 rounded bg-amber-950/30 border-l-2 border-amber-500 text-[10px] text-amber-200/90 font-serif-sc">
              ${rep.canon_reference}
            </blockquote>
            <p class="text-emerald-400/90 text-[11px] leading-tight pt-1">
              <strong>${isEn ? 'Action: ' : '战术行持：'}</strong>${rep.action_item}
            </p>
          </div>
        `;
      });

      stratHtml += `</div>`;
      stratCard.innerHTML = stratHtml;
    }
  }

  function initPoliticalGameControls() {
    ['gameStemMe', 'gameStemBoss', 'gameStemRival', 'gameStemAlly'].forEach(id => {
      const el = document.getElementById(id);
      if (el) {
        el.addEventListener('change', () => {
          if (id === 'gameStemMe') el.setAttribute('data-user-selected', 'true');
          renderPoliticalGameMatrix(currentBaziResult, currentLuckResult);
        });
      }
    });
  }

  // ==========================================================================
  // 🧭 NOAA 地磁偏角与二十四山校正 (Geomagnetic Declination Calibration)
  // ==========================================================================
  function renderGeomagneticCalibrator(res) {
    if (typeof GeomagneticCorrection === 'undefined') return;
    const calibratorPairs = [
      {
        lat: document.getElementById('geoLatInput'),
        lon: document.getElementById('geoLonInput'),
        heading: document.getElementById('geoMagHeadingInput'),
        btn: document.getElementById('btnCalibGeomagnetic'),
        result: document.getElementById('geoCalibResultContainer')
      },
      {
        lat: document.getElementById('simGeoLatInput'),
        lon: document.getElementById('simGeoLonInput'),
        heading: document.getElementById('simGeoMagHeadingInput'),
        btn: document.getElementById('simBtnCalibGeomagnetic'),
        result: document.getElementById('simGeoCalibResultContainer')
      }
    ];

    calibratorPairs.forEach(pair => {
      const latInput = pair.lat;
      const lonInput = pair.lon;
      const headingInput = pair.heading;
      const btnCalib = pair.btn;
      const resultBox = pair.result;
      if (!resultBox) return;

      if (latInput && !latInput.hasAttribute('data-customized')) {
        const customLon = document.getElementById('customLongitude')?.value;
        if (customLon) lonInput.value = parseFloat(customLon).toFixed(2);
      }

      function doCalibrate() {
        if (!resultBox) return;
        const isEn = (currentLang === 'en');
        const lat = parseFloat(latInput?.value || 39.90);
        const lon = parseFloat(lonInput?.value || 116.40);
        const heading = parseFloat(headingInput?.value || 180.0);
        const year = selectedAnnualYear || 2026;

        const dec = GeomagneticCorrection.getDeclination(lat, lon, year);
        const calib = GeomagneticCorrection.correctCompassHeading(heading, dec, currentLang);

        const statusBadgeClass = calib.isSevereParting ? 'bg-rose-950 text-rose-300 border-rose-600' :
                                calib.isParting ? 'bg-amber-950 text-amber-300 border-amber-600' :
                                'bg-emerald-950 text-emerald-300 border-emerald-600';

        const decDir = dec >= 0 ? (isEn ? 'East (+)' : '东偏 (+)') : (isEn ? 'West (-)' : '西偏 (-)');

        resultBox.innerHTML = `
          <div class="grid grid-cols-2 sm:grid-cols-4 gap-3 pb-3 border-b border-gray-800 text-xs">
            <div>
              <span class="text-gray-400 block">${isEn ? 'Declination:' : '本地地磁偏角:'}</span>
              <span class="text-emerald-300 font-mono font-bold text-sm">${dec}° (${decDir})</span>
            </div>
            <div>
              <span class="text-gray-400 block">${isEn ? 'True Heading:' : '校正真北方位:'}</span>
              <span class="text-amber-300 font-mono font-bold text-sm">${calib.trueHeading}°</span>
            </div>
            <div>
              <span class="text-gray-400 block">${isEn ? '24 Mountain:' : '归入二十四山:'}</span>
              <span class="text-cyan-300 font-bold text-sm font-serif-sc">${calib.mountain}</span>
            </div>
            <div>
              <span class="text-gray-400 block">${isEn ? 'Center Offset:' : '山向中心偏离:'}</span>
              <span class="font-mono text-sm ${Math.abs(calib.centerOffset) > 4.5 ? 'text-rose-400 font-bold' : 'text-gray-200'}">${calib.centerOffset > 0 ? '+' : ''}${calib.centerOffset}°</span>
            </div>
          </div>
          <div class="mt-3 p-3 rounded-lg bg-black/30 border border-gray-800 space-y-1.5 text-xs">
            <div class="flex items-center gap-2">
              <span class="px-2 py-0.5 rounded-full border text-[10px] font-mono ${statusBadgeClass}">
                ${calib.isSevereParting ? (isEn ? 'SEVERE PARTING' : '严重出卦兼向') : calib.isParting ? (isEn ? 'CUSP PARTING' : '兼向立局') : (isEn ? 'PURE MOUNTAIN' : '正向纯清')}
              </span>
              <span class="text-gray-200 font-medium">${calib.warning}</span>
            </div>
            <p class="text-emerald-400/90 text-[11px] leading-relaxed">
              <strong>${isEn ? 'Feng Shui Adjustment: ' : '空间形煞调整：'}</strong>${calib.advice}
            </p>
          </div>
        `;
      }

      if (btnCalib && !btnCalib.hasAttribute('data-bound')) {
        btnCalib.setAttribute('data-bound', 'true');
        btnCalib.addEventListener('click', doCalibrate);
      }

      [latInput, lonInput].forEach(inp => {
        if (inp && !inp.hasAttribute('data-bound')) {
          inp.setAttribute('data-bound', 'true');
          inp.addEventListener('input', () => inp.setAttribute('data-customized', 'true'));
        }
      });

      doCalibrate();
    });
  }

  // ==========================================
